('c1000000-0000-4000-8000-000000000002','market','a2000000-0000-4000-8000-000000000001',
 $nsd${"ko":{"name":"홍성농협 하나로마트","description":"홍성농협이 운영하는 마트입니다. 농산물, 축산물, 가공식품, 생필품을 팝니다. 누리집 안내로는 쉬는 날 없이 08:30~22:00에 엽니다."},"en":{"name":"Hongseong Nonghyup Hanaro Mart","description":"A supermarket run by the Hongseong agricultural cooperative. Sells farm produce, meat, processed foods and daily necessities. According to its website it is open every day, 08:30–22:00."},"vi":{"name":"Siêu thị Hanaro Mart Nonghyup Hongseong (홍성농협 하나로마트)","description":"Đây là siêu thị do Hợp tác xã nông nghiệp Hongseong (홍성농협) điều hành. Ở đây bán nông sản, thịt, thực phẩm chế biến và đồ dùng thiết yếu. Theo trang web, siêu thị mở cửa 08:30~22:00, không có ngày nghỉ."},"km":{"name":"ហាណារ៉ូម៉ាត សហករណ៍កសិកម្មហុងសុង (홍성농협 하나로마트)","description":"ជាផ្សារទំនើបដែលសហករណ៍កសិកម្មហុងសុងជាអ្នកបើក។ លក់កសិផល សាច់ អាហារកែច្នៃ និងរបស់ចាំបាច់ប្រចាំថ្ងៃ។ តាមគេហទំព័រ ផ្សារបើកម៉ោង 08:30~22:00 គ្មានថ្ងៃឈប់ទេ។"},"th":{"name":"ฮานาโรมาร์ท สหกรณ์การเกษตรฮงซอง (홍성농협 하나로마트)","description":"เป็นร้านมาร์ทของสหกรณ์การเกษตรฮงซอง ขายผักผลไม้ เนื้อสัตว์ อาหารแปรรูป และของใช้จำเป็น เว็บไซต์ของร้านบอกว่าเปิดทุกวัน ไม่มีวันหยุด เวลา 08:30~22:00"},"ne":{"name":"होङसङ नोङह्योप हानारो मार्ट (홍성농협 하나로마트)","description":"यो होङसङ कृषि सहकारी (नोङह्योप) ले चलाएको मार्ट हो। यहाँ कृषि उपज, मासु, प्रशोधित खाना र दैनिक चाहिने सामान बेचिन्छ। वेबसाइटको जानकारीअनुसार यो बिदा नलिई हरेक दिन 08:30~22:00 सम्म खुल्छ।"},"mn":{"name":"Хунсон Нунхёб Ханаро Март (홍성농협 하나로마트)","description":"Хунсоны хөдөө аж ахуйн хоршооны (Нунхёб) ажиллуулдаг дэлгүүр юм. Газар тариалангийн бүтээгдэхүүн, малын гаралтай бүтээгдэхүүн, боловсруулсан хүнс, өдөр тутмын хэрэглээний бараа зардаг. Вэб сайтад бичсэнээр амрах өдөргүй, 08:30~22:00 цагт ажилладаг."},"uz":{"name":"Hongseong Nonghyup Hanaro Mart (홍성농협 하나로마트)","description":"Hongseong qishloq xoʻjaligi kooperativi (Nonghyup) boshqaradigan market. Qishloq xoʻjaligi mahsulotlari, chorva mahsulotlari, qayta ishlangan oziq-ovqat va kundalik zarur buyumlar sotiladi. Saytidagi maʼlumotga koʻra, har kuni, dam olish kunisiz 08:30~22:00 da ishlaydi."},"ru":{"name":"Ханаро-март кооператива Нонхёп в Хонсоне (홍성농협 하나로마트)","description":"Это магазин сельского кооператива Нонхёп в Хонсоне. Здесь продают овощи и фрукты, мясо, фасованные продукты и товары первой необходимости. По информации на сайте, магазин работает без выходных, 08:30~22:00."}}$nsd$::jsonb,
