insert into public.life_info (id, category, region_id, localized_content, address, phone, source_url, latitude, longitude, verified_at, is_published) values
('c1000000-0000-4000-8000-000000000007','other','a2000000-0000-4000-8000-000000000003',
 $nsd${"ko":{"name":"베트남노상식당 내포점","description":"쌀국수와 동남아 음식을 파는 식당입니다. 쌀국수, 팟타이, 나시고렝, 분짜를 팝니다. 전화번호는 아래 출처(지도)에서 확인하세요."},"en":{"name":"Vietnam Nosang Sikdang, Naepo branch","description":"A restaurant serving pho and other Southeast Asian dishes: pho, pad thai, nasi goreng and bun cha. For the phone number, check the map page under Source below."},"vi":{"name":"Quán Vietnam Nosang Sikdang chi nhánh Naepo (베트남노상식당 내포점)","description":"Đây là quán bán phở và món ăn Đông Nam Á. Quán bán phở, pad Thái, nasi goreng, bún chả. Số điện thoại xin xem ở phần nguồn (bản đồ) bên dưới."},"km":{"name":"ភោជនីយដ្ឋានវៀតណាមណូសាង សាខាណែផូ (베트남노상식당 내포점)","description":"ជាភោជនីយដ្ឋានលក់គុយទាវ និងម្ហូបអាស៊ីអាគ្នេយ៍។ លក់គុយទាវ ផាត់ថៃ ណាស៊ីហ្គោរេង និងប៊ុនចា។ សូមមើលលេខទូរស័ព្ទនៅក្នុងប្រភព (ផែនទី) ខាងក្រោម។"},"th":{"name":"ร้านเวียดนามโนซังชิกดัง สาขาแนโพ (베트남노상식당 내포점)","description":"เป็นร้านขายก๋วยเตี๋ยวและอาหารเอเชียตะวันออกเฉียงใต้ ขายก๋วยเตี๋ยว ผัดไทย นาซีโกเร็ง และบุ๋นจ่า ดูเบอร์โทรได้ที่แหล่งข้อมูล (แผนที่) ด้านล่าง"},"ne":{"name":"भियतनाम नोसाङ रेस्टुरेन्ट नेफो शाखा (베트남노상식당 내포점)","description":"यो चामलको नुडल्स र दक्षिण-पूर्वी एसियाली खाना बेच्ने रेस्टुरेन्ट हो। यहाँ चामलको नुडल्स, प्याड थाई, नासी गोरेङ र बुन चा पाइन्छ। फोन नम्बर तलको स्रोत (नक्सा) मा हेर्नुहोस्।"},"mn":{"name":"Вьетнам Носан хоолны газар, Нэпо салбар (베트남노상식당 내포점)","description":"Будааны гоймон, Зүүн Өмнөд Азийн хоол зардаг хоолны газар юм. Будааны гоймон, пад тай, наси горенг, бүн ча зардаг. Утасны дугаарыг доорх эх сурвалж (газрын зураг)-аас харна уу."},"uz":{"name":"Vietnam Nosang Sikdang, Naepo filiali (베트남노상식당 내포점)","description":"Guruch ugrasi va Janubi-Sharqiy Osiyo taomlari sotiladigan taomxona. Guruch ugrasi, pad-tay, nasi-goreng, bun-cha sotiladi. Telefon raqamini pastdagi manbadan (xarita) koʻring."},"ru":{"name":"Вьетнам Носан Сиктан, Нэпхо (베트남노상식당 내포점)","description":"Это кафе, где готовят рисовую лапшу и блюда Юго-Восточной Азии. Здесь есть рисовая лапша, пад тай, наси горенг и бун ча. Номер телефона смотрите ниже, в источнике (карта)."}}$nsd$::jsonb,
