('c1000000-0000-4000-8000-000000000009','other','a2000000-0000-4000-8000-000000000001',
 $nsd${"ko":{"name":"봄베이키친","description":"인도 커리와 동남아 음식을 파는 식당입니다. 커리, 나시고렝, 쌀국수, 팟타이를 팝니다."},"en":{"name":"Bombay Kitchen","description":"A restaurant serving Indian curries and Southeast Asian dishes: curry, nasi goreng, pho and pad thai."},"vi":{"name":"Quán ăn Bombay Kitchen (봄베이키친)","description":"Đây là quán bán cà ri Ấn Độ và món ăn Đông Nam Á. Quán bán cà ri, nasi goreng, phở, pad Thái."},"km":{"name":"បុមបៃឃីឈិន (봄베이키친)","description":"ជាភោជនីយដ្ឋានលក់ការីឥណ្ឌា និងម្ហូបអាស៊ីអាគ្នេយ៍។ លក់ការី ណាស៊ីហ្គោរេង គុយទាវ និងផាត់ថៃ។"},"th":{"name":"ร้านบอมเบย์คิทเช่น (봄베이키친)","description":"เป็นร้านขายแกงกะหรี่อินเดียและอาหารเอเชียตะวันออกเฉียงใต้ ขายแกงกะหรี่ นาซีโกเร็ง ก๋วยเตี๋ยว และผัดไทย"},"ne":{"name":"बम्बे किचन (봄베이키친)","description":"यो भारतीय करी र दक्षिण-पूर्वी एसियाली खाना बेच्ने रेस्टुरेन्ट हो। यहाँ करी, नासी गोरेङ, चामलको नुडल्स र प्याड थाई पाइन्छ।"},"mn":{"name":"Бомбэй Китчен (봄베이키친)","description":"Энэтхэг карри, Зүүн Өмнөд Азийн хоол зардаг хоолны газар юм. Карри, наси горенг, будааны гоймон, пад тай зардаг."},"uz":{"name":"Bombay Kitchen (봄베이키친)","description":"Hind karrisi va Janubi-Sharqiy Osiyo taomlari sotiladigan taomxona. Karri, nasi-goreng, guruch ugrasi, pad-tay sotiladi."},"ru":{"name":"Бомбей Китчен (봄베이키친)","description":"Это кафе, где готовят индийское карри и блюда Юго-Восточной Азии. Здесь есть карри, наси горенг, рисовая лапша и пад тай."}}$nsd$::jsonb,
