insert into public.life_info (id, category, region_id, localized_content, address, phone, source_url, latitude, longitude, verified_at, is_published) values
('c1000000-0000-4000-8000-000000000011','support','a1000000-0000-4000-8000-000000000001',
 $nsd${"ko":{"name":"외국인력상담센터 ☎1577-0071","description":"일하는 외국인을 위한 상담 전화입니다(한국산업인력공단 운영). 365일 09:00~18:00에 받습니다. 베트남어, 태국어, 캄보디아어, 네팔어, 몽골어, 우즈베크어 등 16개 나라 말로 상담합니다. 러시아어는 안내된 언어 목록에 없습니다."},"en":{"name":"Counseling Center for Foreign Workers ☎1577-0071","description":"A counseling phone line for foreign workers, run by the Human Resources Development Service of Korea. Open 365 days a year, 09:00–18:00. Counseling in the languages of 16 countries, including Vietnamese, Thai, Khmer, Nepali, Mongolian and Uzbek. Russian is not on the published language list."},"vi":{"name":"Trung tâm tư vấn lao động nước ngoài ☎1577-0071 (외국인력상담센터)","description":"Đây là đường dây điện thoại tư vấn cho người nước ngoài đang đi làm (do Cơ quan Phát triển Nguồn nhân lực Hàn Quốc điều hành). Nhận cuộc gọi 365 ngày, 09:00~18:00. Tư vấn bằng tiếng của 16 nước như tiếng Việt, tiếng Thái, tiếng Campuchia, tiếng Nepal, tiếng Mông Cổ, tiếng Uzbek. Tiếng Nga không có trong danh sách ngôn ngữ được thông báo."},"km":{"name":"មជ្ឈមណ្ឌលប្រឹក្សាពលករបរទេស ☎1577-0071 (외국인력상담센터)","description":"ជាទូរស័ព្ទប្រឹក្សាសម្រាប់ជនបរទេសដែលធ្វើការ (ទីភ្នាក់ងារអភិវឌ្ឍន៍ធនធានមនុស្សកូរ៉េជាអ្នកបើក)។ ទទួលទូរស័ព្ទ 365 ថ្ងៃ ម៉ោង 09:00~18:00។ ប្រឹក្សាជាភាសារបស់ប្រទេសចំនួន 16 ដូចជាភាសាវៀតណាម ថៃ ខ្មែរ នេប៉ាល់ ម៉ុងហ្គោលី អ៊ូសបេគីស្ថាន។ ភាសារុស្ស៊ីមិនមានក្នុងបញ្ជីភាសាដែលបានជូនដំណឹងទេ។"},"th":{"name":"ศูนย์ให้คำปรึกษาแรงงานต่างชาติ ☎1577-0071 (외국인력상담센터)","description":"เป็นสายโทรศัพท์ให้คำปรึกษาสำหรับชาวต่างชาติที่ทำงาน (ดูแลโดยสำนักงานพัฒนาทรัพยากรมนุษย์แห่งเกาหลี (한국산업인력공단)) รับสายทุกวันตลอด 365 วัน เวลา 09:00~18:00 ให้คำปรึกษาเป็นภาษาของ 16 ประเทศ เช่น ภาษาเวียดนาม ภาษาไทย ภาษาเขมร ภาษาเนปาล ภาษามองโกเลีย และภาษาอุซเบก ส่วนภาษารัสเซียไม่มีในรายชื่อภาษาที่ประกาศไว้"},"ne":{"name":"विदेशी कामदार परामर्श केन्द्र ☎1577-0071 (외국인력상담센터)","description":"यो काम गर्ने विदेशीका लागि परामर्श फोन हो (कोरिया मानव संसाधन विकास सेवाले चलाएको)। वर्षको 365 दिनै 09:00~18:00 सम्म फोन उठाइन्छ। भियतनामी, थाई, खमेर, नेपाली, मङ्गोलियन, उज्बेक लगायत 16 देशका भाषामा परामर्श हुन्छ। रूसी भाषा जानकारीमा दिइएको भाषाको सूचीमा छैन।"},"mn":{"name":"Гадаад ажилчдын зөвлөгөөний төв ☎1577-0071 (외국인력상담센터)","description":"Ажил хийж байгаа гадаад хүмүүст зориулсан зөвлөгөөний утас юм (Солонгосын хүний нөөцийн хөгжлийн газар (한국산업인력공단) ажиллуулдаг). Жилийн 365 өдөр, 09:00~18:00 цагт утас авна. Вьетнам, тайланд, камбож, непал, монгол, узбек зэрэг 16 орны хэлээр зөвлөгөө өгнө. Орос хэл нь зарласан хэлний жагсаалтад байхгүй."},"uz":{"name":"Chet ellik ishchilar uchun maslahat markazi ☎1577-0071 (외국인력상담센터)","description":"Ishlayotgan chet elliklar uchun maslahat telefoni (Koreya Inson resurslarini rivojlantirish xizmati boshqaradi). Yilning 365 kuni 09:00~18:00 da qabul qiladi. Vyetnam, tay, kambodja (kxmer), nepal, moʻgʻul, oʻzbek tillari kabi 16 mamlakat tilida maslahat beradi. Rus tili eʼlon qilingan tillar roʻyxatida yoʻq."},"ru":{"name":"Консультационный центр для иностранных работников ☎1577-0071 (외국인력상담센터)","description":"Это телефон консультаций для иностранцев, которые работают в Корее (им управляет Корейская служба развития трудовых ресурсов). Звонки принимают 365 дней в году, 09:00~18:00. Консультируют на языках 16 стран: на вьетнамском, тайском, кхмерском, непальском, монгольском, узбекском и других. Русского языка в опубликованном списке языков нет."}}$nsd$::jsonb,
 null,$nsd$1577-0071$nsd$,$nsd$https://www.gov.kr/portal/foreigner/ko/m020401$nsd$,null,null,'2026-10-13',true)
