-- H12 충남 외국인주민 통합지원 콜센터 ☎1522-1866 [홍성군] 출처 구분: 공식 출처(상담전화)
-- 근거: https://www.gongju.go.kr/vt/sub03_02.do , https://www.chungnam.go.kr/eng/main/contents.do?menuNo=6400031
insert into public.life_info (id, category, region_id, localized_content, address, phone, source_url, latitude, longitude, verified_at, is_published) values
('c1000000-0000-4000-8000-000000000012','support','a1000000-0000-4000-8000-000000000001',
 $nsd${"ko":{"name":"충남 외국인주민 통합지원 콜센터 ☎1522-1866","description":"충청남도의 외국인 주민 상담 전화입니다. 생활 정보, 출입국 상담, 일터 고충 상담, 3자 통화 통역을 무료로 돕습니다. 월요일~토요일 09:00~18:00, 일요일은 09:00~16:00에 받습니다. 베트남어, 네팔어, 우즈베크어, 러시아어로 상담하고, 캄보디아어, 태국어, 몽골어는 요일에 따라 됩니다(2024년 6월 안내 기준)."},"en":{"name":"Chungnam Call Center for Foreign Residents ☎1522-1866","description":"Chungcheongnam-do Province's counseling line for foreign residents. Free help with daily-life information, immigration questions, workplace problems, and three-way phone interpretation. Open Monday–Saturday 09:00–18:00, and Sunday 09:00–16:00. Counseling in Vietnamese, Nepali, Uzbek and Russian; Khmer, Thai and Mongolian are available on certain days (as of a June 2024 notice)."},"vi":{"name":"Tổng đài hỗ trợ người nước ngoài tỉnh Chungnam ☎1522-1866 (충남 외국인주민 통합지원 콜센터)","description":"Đây là đường dây điện thoại tư vấn cho người nước ngoài sống ở tỉnh Chungcheongnam (충청남도). Tổng đài giúp miễn phí: thông tin đời sống, tư vấn xuất nhập cảnh, tư vấn khó khăn ở nơi làm việc, phiên dịch qua cuộc gọi 3 bên. Nhận cuộc gọi thứ Hai~thứ Bảy 09:00~18:00, Chủ nhật 09:00~16:00. Tư vấn bằng tiếng Việt, tiếng Nepal, tiếng Uzbek, tiếng Nga; tiếng Campuchia, tiếng Thái, tiếng Mông Cổ thì tùy theo ngày trong tuần (theo thông báo tháng 6 năm 2024)."},"km":{"name":"មជ្ឈមណ្ឌលទូរស័ព្ទជួយជនបរទេស ខេត្តឈុងណាម ☎1522-1866 (충남 외국인주민 통합지원 콜센터)","description":"ជាទូរស័ព្ទប្រឹក្សាសម្រាប់ជនបរទេសដែលរស់នៅខេត្តឈុងឆងណាម។ ជួយដោយឥតគិតថ្លៃ៖ ព័ត៌មានការរស់នៅ ប្រឹក្សារឿងចូលចេញប្រទេស ប្រឹក្សាបញ្ហានៅកន្លែងធ្វើការ និងបកប្រែតាមទូរស័ព្ទ 3 នាក់។ ទទួលទូរស័ព្ទថ្ងៃច័ន្ទ~ថ្ងៃសៅរ៍ ម៉ោង 09:00~18:00 និងថ្ងៃអាទិត្យ ម៉ោង 09:00~16:00។ ប្រឹក្សាជាភាសាវៀតណាម នេប៉ាល់ អ៊ូសបេគីស្ថាន និងរុស្ស៊ី។ ភាសាខ្មែរ ថៃ និងម៉ុងហ្គោលី មានតែថ្ងៃខ្លះក្នុងសប្តាហ៍ (តាមសេចក្តីជូនដំណឹងខែ 6 ឆ្នាំ 2024)។"},"th":{"name":"คอลเซ็นเตอร์ช่วยเหลือชาวต่างชาติ จังหวัดชุงนัม ☎1522-1866 (충남 외국인주민 통합지원 콜센터)","description":"เป็นสายโทรศัพท์ให้คำปรึกษาสำหรับชาวต่างชาติที่อาศัยในจังหวัดชุงชองนัม ช่วยฟรีเรื่องข้อมูลการใช้ชีวิต ปรึกษาเรื่องตรวจคนเข้าเมือง ปรึกษาปัญหาในที่ทำงาน และล่ามทางโทรศัพท์แบบ 3 สาย รับสายวันจันทร์~วันเสาร์ เวลา 09:00~18:00 วันอาทิตย์ เวลา 09:00~16:00 ให้คำปรึกษาเป็นภาษาเวียดนาม ภาษาเนปาล ภาษาอุซเบก และภาษารัสเซีย ส่วนภาษาเขมร ภาษาไทย และภาษามองโกเลีย มีเฉพาะบางวันในสัปดาห์ (ตามประกาศเดือนมิถุนายน 2024)"},"ne":{"name":"छुङनाम विदेशी बासिन्दा एकीकृत सहायता कल सेन्टर ☎1522-1866 (충남 외국인주민 통합지원 콜센터)","description":"यो छुङछङनाम-दो प्रदेशको विदेशी बासिन्दाका लागि परामर्श फोन हो। दैनिक जीवनको जानकारी, अध्यागमन परामर्श, काम गर्ने ठाउँको समस्याको परामर्श र 3 पक्षीय फोन कलमा दोभासे सेवा निःशुल्क पाइन्छ। सोमबार~शनिबार 09:00~18:00, आइतबार 09:00~16:00 सम्म फोन उठाइन्छ। भियतनामी, नेपाली, उज्बेक र रूसी भाषामा परामर्श हुन्छ, र खमेर, थाई, मङ्गोलियन भाषा बारअनुसार मात्र हुन्छ (2024 सालको जुनको जानकारीअनुसार)।"},"mn":{"name":"Чүннам гадаад иргэдэд туслах нэгдсэн дуудлагын төв ☎1522-1866 (충남 외국인주민 통합지원 콜센터)","description":"Өмнөд Чүнчон мужийн гадаад иргэдэд зориулсан зөвлөгөөний утас юм. Амьдралын мэдээлэл, цагаачлалын зөвлөгөө, ажлын байрны бэрхшээлийн зөвлөгөө, 3 талын утасны орчуулгаар үнэгүй тусална. Даваа~Бямба гараг 09:00~18:00, Ням гараг 09:00~16:00 цагт утас авна. Вьетнам, непал, узбек, орос хэлээр зөвлөгөө өгнө. Камбож, тайланд, монгол хэл нь гарагаас хамаарч боломжтой (2024 оны 6-р сарын мэдээллээр)."},"uz":{"name":"Chungnam chet ellik aholiga yordam koll-markazi ☎1522-1866 (충남 외국인주민 통합지원 콜센터)","description":"Chungcheongnam-do viloyatining chet ellik aholi uchun maslahat telefoni. Kundalik hayot haqida maʼlumot, kirish-chiqish (migratsiya) boʻyicha maslahat, ish joyidagi qiyinchiliklar boʻyicha maslahat va 3 tomonlama telefon tarjimasi bilan bepul yordam beradi. Dushanbadan shanbagacha 09:00~18:00, yakshanba kuni 09:00~16:00 da qabul qiladi. Vyetnam, nepal, oʻzbek va rus tillarida maslahat beradi, kambodja (kxmer), tay va moʻgʻul tillari esa hafta kuniga qarab boʻladi (2024-yil iyun oyidagi maʼlumot boʻyicha)."},"ru":{"name":"Колл-центр помощи иностранцам провинции Чхуннам ☎1522-1866 (충남 외국인주민 통합지원 콜센터)","description":"Это телефон консультаций для иностранных жителей провинции Чхунчхон-Намдо. Здесь бесплатно помогают: дают полезную информацию для жизни, консультируют по визам и пребыванию, по трудностям на работе, переводят во время разговора по телефону втроём. Звонки принимают с понедельника по субботу 09:00~18:00, в воскресенье — 09:00~16:00. Консультируют на вьетнамском, непальском, узбекском и русском языках, а на кхмерском, тайском и монгольском — в определённые дни недели (по объявлению от июня 2024 года)."}}$nsd$::jsonb,
 null,$nsd$1522-1866$nsd$,$nsd$https://www.chungnam.go.kr/eng/main/contents.do?menuNo=6400031$nsd$,null,null,'2026-10-13',true)
on conflict (id) do nothing;

-- H13 나라별 안내: 음식점·식재료·모국어 상담 [홍성군] 출처 구분: 위 항목들의 요약(나라별 질답)
insert into public.life_info (id, category, region_id, localized_content, address, phone, source_url, latitude, longitude, verified_at, is_published) values
('c1000000-0000-4000-8000-000000000013','support','a1000000-0000-4000-8000-000000000001',
 $nsd${"ko":{"name":"나라별 안내: 음식점·식재료·모국어 상담","description":"2026년 10월에 확인한 내용입니다.\n베트남: 음식점 4곳 — 흐엉비엣, 헬로베트남(홍성읍), 포텐베트남, 베트남노상식당(홍북읍).\n태국: 음식점 1곳 — 른롬(홍성읍).\n네팔, 몽골, 캄보디아, 우즈베키스탄: 이 나라 음식점은 찾지 못했습니다. 인도 음식점 봄베이키친이 홍성읍에 있습니다.\n식재료: 아시아 식품점은 지도에 몇 곳 있지만 확인을 마치지 못해 싣지 않았습니다. 결성농협 하나로마트가 동남아 식재료 코너를 만들었다는 2022년 보도가 있습니다. 지금도 있는지는 확인하지 못했습니다.\n모국어 상담 전화 1577-0071: 베트남어, 태국어, 캄보디아어, 네팔어, 몽골어, 우즈베크어. 365일 09:00~18:00.\n모국어 상담 전화 1345: 러시아어 등 20개 언어(우즈베크어는 안내에 없습니다). 평일 09:00~22:00, 18:00 이후는 한국어, 영어, 중국어만 됩니다."},"en":{"name":"Guide by country: restaurants, groceries, help in your language","description":"Checked in October 2026.\nVietnam: 4 restaurants — Huong Viet, Hello Vietnam (Hongseong-eup), Poten Vietnam, Vietnam Nosang Sikdang (Hongbuk-eup).\nThailand: 1 restaurant — Reunrom (Hongseong-eup).\nNepal, Mongolia, Cambodia, Uzbekistan: we found no restaurant from these countries. There is an Indian restaurant, Bombay Kitchen, in Hongseong-eup.\nGroceries: a few Asian grocery shops appear on the map, but we could not finish checking them, so they are not listed. A 2022 news report said Gyeolseong Nonghyup Hanaro Mart set up a Southeast Asian ingredients section. We could not confirm whether it still exists.\nPhone help in your language, 1577-0071: Vietnamese, Thai, Khmer, Nepali, Mongolian, Uzbek. 365 days a year, 09:00–18:00.\nPhone help in your language, 1345: 20 languages including Russian (Uzbek is not on the list). Weekdays 09:00–22:00; after 18:00 only Korean, English and Chinese."},"vi":{"name":"Hướng dẫn theo nước: quán ăn, thực phẩm, tư vấn bằng tiếng mẹ đẻ","description":"Nội dung này được kiểm tra vào tháng 10 năm 2026.\nViệt Nam: 4 quán ăn — Huong Viet (흐엉비엣), Hello Vietnam (헬로베트남) ở thị trấn Hongseong (홍성읍); Poten Vietnam (포텐베트남), Vietnam Nosang Sikdang (베트남노상식당) ở thị trấn Hongbuk (홍북읍).\nThái Lan: 1 quán ăn — Reunrom (른롬) ở thị trấn Hongseong.\nNepal, Mông Cổ, Campuchia, Uzbekistan: chúng tôi không tìm thấy quán ăn của các nước này. Có quán ăn Ấn Độ Bombay Kitchen (봄베이키친) ở thị trấn Hongseong.\nThực phẩm: trên bản đồ có vài cửa hàng thực phẩm châu Á, nhưng chúng tôi chưa kiểm tra xong nên không đăng. Có bài báo năm 2022 nói rằng siêu thị Hanaro Mart Nonghyup Gyeolseong (결성농협 하나로마트) đã mở quầy thực phẩm Đông Nam Á. Chúng tôi chưa xác nhận được hiện nay quầy này còn hay không.\nĐiện thoại tư vấn bằng tiếng mẹ đẻ 1577-0071: tiếng Việt, tiếng Thái, tiếng Campuchia, tiếng Nepal, tiếng Mông Cổ, tiếng Uzbek. 365 ngày, 09:00~18:00.\nĐiện thoại tư vấn bằng tiếng mẹ đẻ 1345: 20 ngôn ngữ, trong đó có tiếng Nga (tiếng Uzbek không có trong thông báo). Ngày thường 09:00~22:00, sau 18:00 chỉ có tiếng Hàn, tiếng Anh, tiếng Trung."},"km":{"name":"ព័ត៌មានតាមប្រទេស៖ ភោជនីយដ្ឋាន គ្រឿងធ្វើម្ហូប ប្រឹក្សាជាភាសារបស់អ្នក","description":"នេះជាព័ត៌មានដែលបានពិនិត្យនៅខែ 10 ឆ្នាំ 2026។\nវៀតណាម៖ ភោជនីយដ្ឋាន 4 កន្លែង — ហឿងវៀត (흐엉비엣), ហេឡូវៀតណាម (헬로베트남) នៅទីប្រជុំជនហុងសុង (홍성읍), ផូថេនវៀតណាម (포텐베트남), ភោជនីយដ្ឋានវៀតណាមណូសាង (베트남노상식당) នៅទីប្រជុំជនហុងប៊ុក (홍북읍)។\nថៃ៖ ភោជនីយដ្ឋាន 1 កន្លែង — រឺនរ៉ម (른롬) នៅទីប្រជុំជនហុងសុង។\nនេប៉ាល់ ម៉ុងហ្គោលី កម្ពុជា អ៊ូសបេគីស្ថាន៖ យើងរកមិនឃើញភោជនីយដ្ឋានម្ហូបប្រទេសទាំងនេះទេ។ មានភោជនីយដ្ឋានម្ហូបឥណ្ឌា បុមបៃឃីឈិន (봄베이키친) នៅទីប្រជុំជនហុងសុង។\nគ្រឿងធ្វើម្ហូប៖ នៅលើផែនទីមានហាងលក់អាហារអាស៊ីពីរបីកន្លែង ប៉ុន្តែយើងពិនិត្យមិនទាន់ចប់ ទើបមិនបានដាក់នៅទីនេះ។ មានព័ត៌មានឆ្នាំ 2022 ថា ហាណារ៉ូម៉ាត សហករណ៍កសិកម្មគ្យលសុង (결성농협 하나로마트) បានបង្កើតកន្លែងលក់គ្រឿងធ្វើម្ហូបអាស៊ីអាគ្នេយ៍។ យើងមិនទាន់បានបញ្ជាក់ថាឥឡូវនៅមានឬអត់ទេ។\nទូរស័ព្ទប្រឹក្សាជាភាសារបស់អ្នក 1577-0071៖ ភាសាវៀតណាម ថៃ ខ្មែរ នេប៉ាល់ ម៉ុងហ្គោលី អ៊ូសបេគីស្ថាន។ 365 ថ្ងៃ ម៉ោង 09:00~18:00។\nទូរស័ព្ទប្រឹក្សាជាភាសារបស់អ្នក 1345៖ 20 ភាសា រួមទាំងភាសារុស្ស៊ី (ភាសាអ៊ូសបេគីស្ថានមិនមានក្នុងសេចក្តីជូនដំណឹងទេ)។ ថ្ងៃធ្វើការ ម៉ោង 09:00~22:00។ ក្រោយម៉ោង 18:00 មានតែភាសាកូរ៉េ អង់គ្លេស និងចិនប៉ុណ្ណោះ។"},"th":{"name":"ข้อมูลแยกตามประเทศ: ร้านอาหาร·วัตถุดิบ·ปรึกษาเป็นภาษาของคุณ","description":"ข้อมูลนี้ตรวจสอบเมื่อเดือนตุลาคม 2026\nเวียดนาม: ร้านอาหาร 4 ร้าน — ฮือองบีเอ็ต (흐엉비엣), เฮลโลเวียดนาม (헬로베트남) (ตำบลฮงซอง (홍성읍)), โพเทนเวียดนาม (포텐베트남), เวียดนามโนซังชิกดัง (베트남노상식당) (ตำบลฮงบุก (홍북읍))\nไทย: ร้านอาหาร 1 ร้าน — รึนรม (른롬) (ตำบลฮงซอง)\nเนปาล มองโกเลีย กัมพูชา อุซเบกิสถาน: เราหาร้านอาหารของประเทศเหล่านี้ไม่พบ มีร้านอาหารอินเดียชื่อบอมเบย์คิทเช่น (봄베이키친) อยู่ที่ตำบลฮงซอง\nวัตถุดิบ: ในแผนที่มีร้านขายอาหารเอเชียอยู่ไม่กี่ร้าน แต่เรายังตรวจสอบไม่เสร็จ จึงไม่ได้ลงไว้ มีข่าวปี 2022 ว่าฮานาโรมาร์ท สหกรณ์การเกษตรคยอลซอง (결성농협 하나로마트) ทำมุมขายวัตถุดิบเอเชียตะวันออกเฉียงใต้ เรายังตรวจสอบไม่ได้ว่าตอนนี้ยังมีอยู่หรือไม่\nสายปรึกษาเป็นภาษาของคุณ 1577-0071: ภาษาเวียดนาม ภาษาไทย ภาษาเขมร ภาษาเนปาล ภาษามองโกเลีย ภาษาอุซเบก 365 วัน เวลา 09:00~18:00\nสายปรึกษาเป็นภาษาของคุณ 1345: 20 ภาษา เช่น ภาษารัสเซีย (ภาษาอุซเบกไม่มีในประกาศ) วันธรรมดา 09:00~22:00 หลัง 18:00 มีเฉพาะภาษาเกาหลี ภาษาอังกฤษ และภาษาจีน"},"ne":{"name":"देशअनुसार जानकारी: रेस्टुरेन्ट, खाद्य सामग्री, आफ्नै भाषामा परामर्श","description":"यो 2026 सालको अक्टोबरमा जाँचिएको जानकारी हो।\nभियतनाम: रेस्टुरेन्ट 4 वटा — हउङ बिएत (흐엉비엣), हेलो भियतनाम (헬로베트남) [होङसङ-उप (홍성읍)], पोतेन भियतनाम (포텐베트남), भियतनाम नोसाङ रेस्टुरेन्ट (베트남노상식당) [होङबुक-उप (홍북읍)]।\nथाइल्याण्ड: रेस्टुरेन्ट 1 वटा — रुन्रोम (른롬) [होङसङ-उप]।\nनेपाल, मङ्गोलिया, कम्बोडिया, उज्बेकिस्तान: यी देशका रेस्टुरेन्ट हामीले भेट्टाएनौँ। भारतीय रेस्टुरेन्ट बम्बे किचन (봄베이키친) होङसङ-उपमा छ।\nखाद्य सामग्री: नक्सामा एसियाली खाद्य पसल केही छन्, तर जाँच पूरा गर्न नसकेकाले यहाँ राखिएको छैन। ग्योल्सङ नोङह्योप हानारो मार्ट (결성농협 하나로마트) ले दक्षिण-पूर्वी एसियाली खाद्य सामग्रीको कुना बनाएको भन्ने 2022 सालको समाचार छ। त्यो अहिले पनि छ कि छैन, हामीले पक्का गर्न सकेनौँ।\nआफ्नै भाषामा परामर्श फोन 1577-0071: भियतनामी, थाई, खमेर, नेपाली, मङ्गोलियन, उज्बेक। वर्षको 365 दिनै 09:00~18:00।\nआफ्नै भाषामा परामर्श फोन 1345: रूसी लगायत 20 भाषा (उज्बेक भाषा जानकारीमा छैन)। सोमबार~शुक्रबार 09:00~22:00, 18:00 पछि कोरियन, अङ्ग्रेजी र चिनियाँ भाषा मात्र हुन्छ।"},"mn":{"name":"Улс орноор мэдээлэл: хоолны газар, хүнсний бараа, эх хэлээрээ зөвлөгөө","description":"2026 оны 10-р сард шалгасан мэдээлэл.\nВьетнам: хоолны газар 4 — Хунсон суурин (홍성읍)-д Хыон Вьет (흐엉비엣), Хэлло Вьетнам (헬로베트남); Хунбүк суурин (홍북읍)-д Потен Вьетнам (포텐베트남), Вьетнам Носан хоолны газар (베트남노상식당).\nТайланд: хоолны газар 1 — Рынром (른롬), Хунсон суурин.\nНепал, Монгол, Камбож, Узбекистан: эдгээр орны хоолны газар олдоогүй. Энэтхэг хоолны газар Бомбэй Китчен (봄베이키친) Хунсон сууринд байдаг.\nХүнсний бараа: газрын зураг дээр Азийн хүнсний дэлгүүр хэд хэд байгаа ч шалгаж дуусаагүй тул энд оруулаагүй. Гёлсон Нунхёб Ханаро Март (결성농협 하나로마트) Зүүн Өмнөд Азийн хүнсний барааны булан гаргасан гэсэн 2022 оны мэдээ бий. Одоо байгаа эсэхийг шалгаж чадаагүй.\nЭх хэлээрээ зөвлөгөө авах утас 1577-0071: вьетнам, тайланд, камбож, непал, монгол, узбек хэл. Жилийн 365 өдөр, 09:00~18:00.\nЭх хэлээрээ зөвлөгөө авах утас 1345: орос зэрэг 20 хэл (узбек хэл мэдээлэлд байхгүй). Ажлын өдөр 09:00~22:00, 18:00 цагаас хойш зөвхөн солонгос, англи, хятад хэлээр."},"uz":{"name":"Mamlakatlar boʻyicha maʼlumot: taomxona, oziq-ovqat, ona tilida maslahat","description":"2026-yil oktyabr oyida tekshirilgan maʼlumot.\nVyetnam: 4 ta taomxona — Huong Viet (흐엉비엣) va Hello Vietnam (헬로베트남) — Hongseong shaharchasida (홍성읍); Poten Vietnam (포텐베트남) va Vietnam Nosang Sikdang (베트남노상식당) — Hongbuk shaharchasida (홍북읍).\nTailand: 1 ta taomxona — Rinrom (른롬), Hongseong shaharchasida.\nNepal, Moʻgʻuliston, Kambodja, Oʻzbekiston: bu mamlakatlar taomxonasini topa olmadik. Hongseong shaharchasida hind taomxonasi Bombay Kitchen (봄베이키친) bor.\nOziq-ovqat mahsulotlari: xaritada bir nechta Osiyo oziq-ovqat doʻkoni bor, lekin tekshirib ulgurmadik, shuning uchun bu yerga kiritmadik. Gyeolseong Nonghyup Hanaro Mart (결성농협 하나로마트) Janubi-Sharqiy Osiyo mahsulotlari boʻlimini ochgani haqida 2022-yilgi xabar bor. Hozir ham bor-yoʻqligini aniqlay olmadik.\nOna tilida maslahat telefoni 1577-0071: vyetnam, tay, kambodja (kxmer), nepal, moʻgʻul, oʻzbek tillari. Yilning 365 kuni 09:00~18:00.\nOna tilida maslahat telefoni 1345: rus tili va boshqa tillar, jami 20 ta til (oʻzbek tili maʼlumotda koʻrsatilmagan). Ish kunlari 09:00~22:00, 18:00 dan keyin faqat koreys, ingliz va xitoy tillarida."},"ru":{"name":"По странам: кафе, продукты, помощь на вашем языке","description":"Эти сведения проверены в октябре 2026 года.\nВьетнам: 4 кафе — Хыонг Вьет (흐엉비엣), Хелло Вьетнам (헬로베트남) [посёлок Хонсон (홍성읍)], Потен Вьетнам (포텐베트남), Вьетнам Носан Сиктан (베트남노상식당) [посёлок Хонбук (홍북읍)].\nТаиланд: 1 кафе — Рынром (른롬) [посёлок Хонсон].\nНепал, Монголия, Камбоджа, Узбекистан: кафе с кухней этих стран мы не нашли. В посёлке Хонсон есть индийское кафе Бомбей Китчен (봄베이키친).\nПродукты: на карте есть несколько азиатских продуктовых магазинов, но мы не успели их проверить и поэтому не добавили. В 2022 году в новостях писали, что в Ханаро-марте кооператива Нонхёп в Кёльсоне (결성농협 하나로마트) сделали отдел продуктов из Юго-Восточной Азии. Есть ли он сейчас, мы не смогли проверить.\nТелефон помощи на вашем языке 1577-0071: вьетнамский, тайский, кхмерский, непальский, монгольский, узбекский. 365 дней в году, 09:00~18:00.\nТелефон помощи на вашем языке 1345: 20 языков, в том числе русский (узбекского в объявлении нет). В будни 09:00~22:00, после 18:00 — только корейский, английский и китайский."}}$nsd$::jsonb,
 null,$nsd$1345$nsd$,null,null,null,'2026-10-13',true)
