insert into public.life_info (id, category, region_id, localized_content, address, phone, source_url, latitude, longitude, verified_at, is_published) values
('c1000000-0000-4000-8000-000000000014','market','a1000000-0000-4000-8000-000000000014',
 $nsd${"ko":{"name":"아시아 마트 · 신례원","description":"이름이 '아시아 마트'인 가게입니다. 지도에는 슈퍼마켓으로 등록돼 있습니다. 어느 나라 식품을 파는지는 확인하지 못했습니다."},"en":{"name":"Asia Mart · Sillyewon","description":"A shop named 'Asia Mart'. It is listed on the map as a supermarket. We could not confirm which countries' foods it sells."},"vi":{"name":"Cửa hàng Asia Mart · Sillyewon (아시아 마트 · 신례원)","description":"Đây là cửa hàng có tên 'Asia Mart'. Trên bản đồ, cửa hàng được đăng ký là siêu thị. Chúng tôi chưa xác nhận được cửa hàng bán thực phẩm của nước nào."},"km":{"name":"អាស៊ីម៉ាត · ស៊ីលយេវ៉ុន (아시아 마트 · 신례원)","description":"ជាហាងដែលមានឈ្មោះថា «អាស៊ីម៉ាត» (아시아 마트)។ នៅលើផែនទី ហាងនេះចុះឈ្មោះជាផ្សារទំនើប។ យើងមិនទាន់បានបញ្ជាក់ថាហាងលក់អាហាររបស់ប្រទេសណាទេ។"},"th":{"name":"เอเชียมาร์ท · ชิลเลวอน (아시아 마트 · 신례원)","description":"เป็นร้านที่ชื่อว่า 'เอเชียมาร์ท' ในแผนที่ลงทะเบียนเป็นซูเปอร์มาร์เก็ต เรายังตรวจสอบไม่ได้ว่าขายอาหารของประเทศไหน"},"ne":{"name":"एसिया मार्ट · सिल्लेवन (아시아 마트 · 신례원)","description":"यो 'एसिया मार्ट' नाम भएको पसल हो। नक्सामा यो सुपरमार्केटको रूपमा दर्ता छ। यहाँ कुन देशको खाद्य सामग्री बेचिन्छ, हामीले पक्का गर्न सकेनौँ।"},"mn":{"name":"Ази Март · Шиллевон (아시아 마트 · 신례원)","description":"«Ази Март» гэдэг нэртэй дэлгүүр юм. Газрын зураг дээр супермаркет гэж бүртгэгдсэн. Аль орны хүнс зардгийг шалгаж чадаагүй."},"uz":{"name":"Asia Mart · Sillyewon (아시아 마트 · 신례원)","description":"Nomi «Asia Mart» boʻlgan doʻkon. Xaritada supermarket sifatida roʻyxatga olingan. Qaysi mamlakat oziq-ovqatlarini sotishini aniqlay olmadik."},"ru":{"name":"Азия Март · Силлевон (아시아 마트 · 신례원)","description":"Это магазин с названием «Азия Март». На карте он записан как супермаркет. Продукты каких стран здесь продают, мы не смогли проверить."}}$nsd$::jsonb,
