('c1000000-0000-4000-8000-000000000015','other','a1000000-0000-4000-8000-000000000014',
 $nsd${"ko":{"name":"퍼휀베트남쌀국수","description":"베트남 쌀국수 음식점입니다. 쇠고기쌀국수, 분짜, 분보후에를 팝니다."},"en":{"name":"Peohwen Vietnamese Rice Noodles","description":"A Vietnamese rice-noodle restaurant. Serves beef pho, bun cha and bun bo Hue."},"vi":{"name":"Quán phở Việt Nam Peohwen (퍼휀베트남쌀국수)","description":"Đây là quán phở Việt Nam. Quán bán phở bò, bún chả, bún bò Huế."},"km":{"name":"ភើហ្វេន គុយទាវវៀតណាម (퍼휀베트남쌀국수)","description":"ជាភោជនីយដ្ឋានគុយទាវវៀតណាម។ លក់គុយទាវសាច់គោ ប៊ុនចា និងប៊ុនបូហ្វេ។"},"th":{"name":"ร้านก๋วยเตี๋ยวเวียดนามพอฮเวน (퍼휀베트남쌀국수)","description":"เป็นร้านก๋วยเตี๋ยวเวียดนาม ขายก๋วยเตี๋ยวเนื้อ บุ๋นจ่า และบุ๋นบ่อเว้"},"ne":{"name":"फोह्वेन भियतनामी चामलको नुडल्स (퍼휀베트남쌀국수)","description":"यो भियतनामी चामलको नुडल्सको रेस्टुरेन्ट हो। यहाँ गाईको मासुको चामलको नुडल्स, बुन चा र बुन बो हुए पाइन्छ।"},"mn":{"name":"Пөхвэн Вьетнам будааны гоймон (퍼휀베트남쌀국수)","description":"Вьетнам будааны гоймонгийн газар юм. Үхрийн махтай будааны гоймон, бүн ча, бүн бо хюэ зардаг."},"uz":{"name":"Pohven Vyetnam guruch ugrasi (퍼휀베트남쌀국수)","description":"Vyetnamcha guruch ugrasi taomxonasi. Mol goʻshtli guruch ugrasi, bun-cha, bun-bo-xue sotiladi."},"ru":{"name":"Пхохвен, вьетнамская рисовая лапша (퍼휀베트남쌀국수)","description":"Это кафе вьетнамской рисовой лапши. Здесь готовят рисовую лапшу с говядиной, бун ча и бун бо хюэ."}}$nsd$::jsonb,
