-- Y05 나라별 안내: 음식점·식재료·모국어 상담 [예산군] 출처 구분: 위 항목들의 요약(나라별 질답)
insert into public.life_info (id, category, region_id, localized_content, address, phone, source_url, latitude, longitude, verified_at, is_published) values
('c1000000-0000-4000-8000-000000000018','support','a1000000-0000-4000-8000-000000000014',
 $nsd${"ko":{"name":"나라별 안내: 음식점·식재료·모국어 상담","description":"2026년 10월에 확인한 내용입니다.\n베트남: 음식점 1곳 — 퍼휀베트남쌀국수(예산읍).\n태국, 네팔, 몽골, 캄보디아, 우즈베키스탄: 이 나라 음식점은 찾지 못했습니다.\n식재료: 예산읍 신례원에 '아시아 마트'라는 가게가 있습니다. 파는 물건은 가서 확인하세요.\n모국어 상담 전화 1577-0071: 베트남어, 태국어, 캄보디아어, 네팔어, 몽골어, 우즈베크어. 365일 09:00~18:00.\n모국어 상담 전화 1345: 러시아어 등 20개 언어(우즈베크어는 안내에 없습니다). 평일 09:00~22:00, 18:00 이후는 한국어, 영어, 중국어만 됩니다."},"en":{"name":"Guide by country: restaurants, groceries, help in your language","description":"Checked in October 2026.\nVietnam: 1 restaurant — Peohwen Vietnamese Rice Noodles (Yesan-eup).\nThailand, Nepal, Mongolia, Cambodia, Uzbekistan: we found no restaurant from these countries.\nGroceries: there is a shop called 'Asia Mart' in Sillyewon, Yesan-eup. Please check on site what it sells.\nPhone help in your language, 1577-0071: Vietnamese, Thai, Khmer, Nepali, Mongolian, Uzbek. 365 days a year, 09:00–18:00.\nPhone help in your language, 1345: 20 languages including Russian (Uzbek is not on the list). Weekdays 09:00–22:00; after 18:00 only Korean, English and Chinese."},"vi":{"name":"Hướng dẫn theo nước: quán ăn, thực phẩm, tư vấn bằng tiếng mẹ đẻ","description":"Nội dung này được kiểm tra vào tháng 10 năm 2026.\nViệt Nam: 1 quán ăn — quán phở Việt Nam Peohwen (퍼휀베트남쌀국수) ở thị trấn Yesan (예산읍).\nThái Lan, Nepal, Mông Cổ, Campuchia, Uzbekistan: chúng tôi không tìm thấy quán ăn của các nước này.\nThực phẩm: ở Sillyewon (신례원), thị trấn Yesan có cửa hàng tên là 'Asia Mart' (아시아 마트). Cửa hàng bán gì thì bạn hãy đến xem.\nĐiện thoại tư vấn bằng tiếng mẹ đẻ 1577-0071: tiếng Việt, tiếng Thái, tiếng Campuchia, tiếng Nepal, tiếng Mông Cổ, tiếng Uzbek. 365 ngày, 09:00~18:00.\nĐiện thoại tư vấn bằng tiếng mẹ đẻ 1345: 20 ngôn ngữ, trong đó có tiếng Nga (tiếng Uzbek không có trong thông báo). Ngày thường 09:00~22:00, sau 18:00 chỉ có tiếng Hàn, tiếng Anh, tiếng Trung."},"km":{"name":"ព័ត៌មានតាមប្រទេស៖ ភោជនីយដ្ឋាន គ្រឿងធ្វើម្ហូប ប្រឹក្សាជាភាសារបស់អ្នក","description":"នេះជាព័ត៌មានដែលបានពិនិត្យនៅខែ 10 ឆ្នាំ 2026។\nវៀតណាម៖ ភោជនីយដ្ឋាន 1 កន្លែង — ភើហ្វេន គុយទាវវៀតណាម (퍼휀베트남쌀국수) នៅទីប្រជុំជនយេសាន (예산읍)។\nថៃ នេប៉ាល់ ម៉ុងហ្គោលី កម្ពុជា អ៊ូសបេគីស្ថាន៖ យើងរកមិនឃើញភោជនីយដ្ឋានម្ហូបប្រទេសទាំងនេះទេ។\nគ្រឿងធ្វើម្ហូប៖ នៅស៊ីលយេវ៉ុន (신례원) ទីប្រជុំជនយេសាន មានហាងមួយឈ្មោះ «អាស៊ីម៉ាត» (아시아 마트)។ សូមទៅមើលដោយផ្ទាល់ថាហាងលក់អ្វីខ្លះ។\nទូរស័ព្ទប្រឹក្សាជាភាសារបស់អ្នក 1577-0071៖ ភាសាវៀតណាម ថៃ ខ្មែរ នេប៉ាល់ ម៉ុងហ្គោលី អ៊ូសបេគីស្ថាន។ 365 ថ្ងៃ ម៉ោង 09:00~18:00។\nទូរស័ព្ទប្រឹក្សាជាភាសារបស់អ្នក 1345៖ 20 ភាសា រួមទាំងភាសារុស្ស៊ី (ភាសាអ៊ូសបេគីស្ថានមិនមានក្នុងសេចក្តីជូនដំណឹងទេ)។ ថ្ងៃធ្វើការ ម៉ោង 09:00~22:00។ ក្រោយម៉ោង 18:00 មានតែភាសាកូរ៉េ អង់គ្លេស និងចិនប៉ុណ្ណោះ។"},"th":{"name":"ข้อมูลแยกตามประเทศ: ร้านอาหาร·วัตถุดิบ·ปรึกษาเป็นภาษาของคุณ","description":"ข้อมูลนี้ตรวจสอบเมื่อเดือนตุลาคม 2026\nเวียดนาม: ร้านอาหาร 1 ร้าน — ร้านก๋วยเตี๋ยวเวียดนามพอฮเวน (퍼휀베트남쌀국수) (ตำบลเยซาน (예산읍))\nไทย เนปาล มองโกเลีย กัมพูชา อุซเบกิสถาน: เราหาร้านอาหารของประเทศเหล่านี้ไม่พบ\nวัตถุดิบ: ที่ชิลเลวอน (신례원) ตำบลเยซาน มีร้านชื่อ 'เอเชียมาร์ท' (아시아 마트) ของที่ขายมีอะไรบ้าง ให้ไปดูที่ร้าน\nสายปรึกษาเป็นภาษาของคุณ 1577-0071: ภาษาเวียดนาม ภาษาไทย ภาษาเขมร ภาษาเนปาล ภาษามองโกเลีย ภาษาอุซเบก 365 วัน เวลา 09:00~18:00\nสายปรึกษาเป็นภาษาของคุณ 1345: 20 ภาษา เช่น ภาษารัสเซีย (ภาษาอุซเบกไม่มีในประกาศ) วันธรรมดา 09:00~22:00 หลัง 18:00 มีเฉพาะภาษาเกาหลี ภาษาอังกฤษ และภาษาจีน"},"ne":{"name":"देशअनुसार जानकारी: रेस्टुरेन्ट, खाद्य सामग्री, आफ्नै भाषामा परामर्श","description":"यो 2026 सालको अक्टोबरमा जाँचिएको जानकारी हो।\nभियतनाम: रेस्टुरेन्ट 1 वटा — फोह्वेन भियतनामी चामलको नुडल्स (퍼휀베트남쌀국수) [येसान-उप (예산읍)]।\nथाइल्याण्ड, नेपाल, मङ्गोलिया, कम्बोडिया, उज्बेकिस्तान: यी देशका रेस्टुरेन्ट हामीले भेट्टाएनौँ।\nखाद्य सामग्री: येसान-उपको सिल्लेवन (신례원) मा 'एसिया मार्ट' (아시아 마트) भन्ने पसल छ। के-के बेचिन्छ, त्यहाँ गएर हेर्नुहोस्।\nआफ्नै भाषामा परामर्श फोन 1577-0071: भियतनामी, थाई, खमेर, नेपाली, मङ्गोलियन, उज्बेक। वर्षको 365 दिनै 09:00~18:00।\nआफ्नै भाषामा परामर्श फोन 1345: रूसी लगायत 20 भाषा (उज्बेक भाषा जानकारीमा छैन)। सोमबार~शुक्रबार 09:00~22:00, 18:00 पछि कोरियन, अङ्ग्रेजी र चिनियाँ भाषा मात्र हुन्छ।"},"mn":{"name":"Улс орноор мэдээлэл: хоолны газар, хүнсний бараа, эх хэлээрээ зөвлөгөө","description":"2026 оны 10-р сард шалгасан мэдээлэл.\nВьетнам: хоолны газар 1 — Пөхвэн Вьетнам будааны гоймон (퍼휀베트남쌀국수), Есан суурин (예산읍).\nТайланд, Непал, Монгол, Камбож, Узбекистан: эдгээр орны хоолны газар олдоогүй.\nХүнсний бараа: Есан суурины Шиллевон (신례원)-д «Ази Март» (아시아 마트) гэдэг дэлгүүр байдаг. Юу зардгийг очиж үзээрэй.\nЭх хэлээрээ зөвлөгөө авах утас 1577-0071: вьетнам, тайланд, камбож, непал, монгол, узбек хэл. Жилийн 365 өдөр, 09:00~18:00.\nЭх хэлээрээ зөвлөгөө авах утас 1345: орос зэрэг 20 хэл (узбек хэл мэдээлэлд байхгүй). Ажлын өдөр 09:00~22:00, 18:00 цагаас хойш зөвхөн солонгос, англи, хятад хэлээр."},"uz":{"name":"Mamlakatlar boʻyicha maʼlumot: taomxona, oziq-ovqat, ona tilida maslahat","description":"2026-yil oktyabr oyida tekshirilgan maʼlumot.\nVyetnam: 1 ta taomxona — Pohven Vyetnam guruch ugrasi (퍼휀베트남쌀국수), Yesan shaharchasida (예산읍).\nTailand, Nepal, Moʻgʻuliston, Kambodja, Oʻzbekiston: bu mamlakatlar taomxonasini topa olmadik.\nOziq-ovqat mahsulotlari: Yesan shaharchasining Sillyewon (신례원) degan joyida «Asia Mart» (아시아 마트) degan doʻkon bor. Nima sotilishini borib koʻring.\nOna tilida maslahat telefoni 1577-0071: vyetnam, tay, kambodja (kxmer), nepal, moʻgʻul, oʻzbek tillari. Yilning 365 kuni 09:00~18:00.\nOna tilida maslahat telefoni 1345: rus tili va boshqa tillar, jami 20 ta til (oʻzbek tili maʼlumotda koʻrsatilmagan). Ish kunlari 09:00~22:00, 18:00 dan keyin faqat koreys, ingliz va xitoy tillarida."},"ru":{"name":"По странам: кафе, продукты, помощь на вашем языке","description":"Эти сведения проверены в октябре 2026 года.\nВьетнам: 1 кафе — Пхохвен, вьетнамская рисовая лапша (퍼휀베트남쌀국수) [посёлок Есан (예산읍)].\nТаиланд, Непал, Монголия, Камбоджа, Узбекистан: кафе с кухней этих стран мы не нашли.\nПродукты: в Силлевоне (신례원), посёлок Есан, есть магазин с названием «Азия Март» (아시아 마트). Что там продают, посмотрите на месте.\nТелефон помощи на вашем языке 1577-0071: вьетнамский, тайский, кхмерский, непальский, монгольский, узбекский. 365 дней в году, 09:00~18:00.\nТелефон помощи на вашем языке 1345: 20 языков, в том числе русский (узбекского в объявлении нет). В будни 09:00~22:00, после 18:00 — только корейский, английский и китайский."}}$nsd$::jsonb,
 null,$nsd$1345$nsd$,null,null,null,'2026-10-13',true)
