('c1000000-0000-4000-8000-000000000019','government','a1000000-0000-4000-8000-000000001201',
 $nsd${"ko":{"name":"밀양시청","description":"시 행정과 민원을 처리하는 밀양시 청사입니다. 대표전화의 점심시간은 12:00~13:00입니다."},"en":{"name":"Miryang City Hall","description":"Miryang's city hall, handling city administration and civil services. The main phone line has a lunch break from 12:00 to 13:00."},"vi":{"name":"Tòa thị chính thành phố Miryang (밀양시청)","description":"Đây là trụ sở thành phố Miryang, nơi làm việc hành chính và giải quyết thủ tục cho người dân. Số điện thoại chính nghỉ trưa 12:00~13:00."},"km":{"name":"សាលាក្រុងមីរយ៉ាង (밀양시청)","description":"ជាអគារសាលាក្រុងមីរយ៉ាង ដែលធ្វើការងាររដ្ឋបាលក្រុង និងទទួលសំណើរបស់ប្រជាជន។ ម៉ោងសម្រាកថ្ងៃត្រង់របស់លេខទូរស័ព្ទទូទៅគឺ 12:00~13:00។"},"th":{"name":"ศาลากลางเมืองมีรยัง (밀양시청)","description":"เป็นอาคารที่ทำการของเมืองมีรยัง ดูแลงานบริหารเมืองและงานบริการประชาชน เบอร์โทรหลักพักกลางวันเวลา 12:00~13:00"},"ne":{"name":"मिर्याङ सहर कार्यालय (밀양시청)","description":"यो सहरको प्रशासन र नागरिकका कागजी काम गर्ने मिर्याङ सहरको कार्यालय भवन हो। मुख्य फोनको खाजा समय 12:00~13:00 हो।"},"mn":{"name":"Мирян хотын захиргаа (밀양시청)","description":"Хотын захиргааны ажил, иргэдийн өргөдөл хүсэлтийг шийддэг Мирян хотын захиргааны байр юм. Ерөнхий утасны үдийн цайны цаг 12:00~13:00."},"uz":{"name":"Miryang shahar hokimligi (밀양시청)","description":"Shahar boshqaruvi va fuqarolar murojaatlari bilan shugʻullanadigan Miryang shahar hokimligi binosi. Asosiy telefon raqamida tushlik tanaffusi 12:00~13:00."},"ru":{"name":"Мэрия города Мирян (밀양시청)","description":"Это здание мэрии города Мирян. Здесь занимаются делами города и принимают обращения жителей. Обеденный перерыв на главном телефоне — 12:00~13:00."}}$nsd$::jsonb,
