 $nsd${"ko":{"name":"밀양시보건소","description":"밀양시가 운영하는 공공 보건소입니다. 누리집 안내로는 09:00~18:00에 열고 토요일, 일요일, 공휴일은 쉽니다."},"en":{"name":"Miryang Public Health Center","description":"A public health center run by Miryang City. According to its website it is open 09:00–18:00 and closed on Saturdays, Sundays and public holidays."},"vi":{"name":"Trung tâm y tế công cộng thành phố Miryang (밀양시보건소)","description":"Đây là trung tâm y tế công cộng do thành phố Miryang điều hành. Theo trang web, trung tâm mở cửa 09:00~18:00, nghỉ thứ Bảy, Chủ nhật và ngày lễ."},"km":{"name":"មណ្ឌលសុខភាពក្រុងមីរយ៉ាង (밀양시보건소)","description":"ជាមណ្ឌលសុខភាពសាធារណៈដែលក្រុងមីរយ៉ាងជាអ្នកបើក។ តាមគេហទំព័រ បើកម៉ោង 09:00~18:00 ហើយឈប់ថ្ងៃសៅរ៍ ថ្ងៃអាទិត្យ និងថ្ងៃបុណ្យជាតិ។"},"th":{"name":"ศูนย์สาธารณสุขเมืองมีรยัง (밀양시보건소)","description":"เป็นศูนย์สาธารณสุขของรัฐที่เมืองมีรยังดูแล ตามข้อมูลในเว็บไซต์ เปิด 09:00~18:00 หยุดวันเสาร์ วันอาทิตย์ และวันหยุดราชการ"},"ne":{"name":"मिर्याङ सहर जनस्वास्थ्य केन्द्र (밀양시보건소)","description":"यो मिर्याङ सहरले चलाएको सरकारी जनस्वास्थ्य केन्द्र हो। वेबसाइटको जानकारीअनुसार 09:00~18:00 सम्म खुल्छ, शनिबार, आइतबार र सार्वजनिक बिदामा बन्द हुन्छ।"},"mn":{"name":"Мирян хотын эрүүл мэндийн төв (밀양시보건소)","description":"Мирян хотын ажиллуулдаг улсын эрүүл мэндийн төв юм. Вэб сайтад бичсэнээр 09:00~18:00 цагт ажиллаж, Бямба гараг, Ням гараг, бүх нийтийн амралтын өдөр амардаг."},"uz":{"name":"Miryang shahar sogʻliqni saqlash markazi (밀양시보건소)","description":"Miryang shahri boshqaradigan davlat sogʻliqni saqlash markazi. Saytidagi maʼlumotga koʻra, 09:00~18:00 da ishlaydi, shanba, yakshanba va bayram kunlari dam oladi."},"ru":{"name":"Центр здоровья города Мирян (밀양시보건소)","description":"Это государственный центр здоровья, которым управляет город Мирян. По информации на сайте, работает 09:00~18:00, в субботу, воскресенье и в праздничные дни закрыт."}}$nsd$::jsonb,
