-- M03 밀양병원 [밀양시] 출처 구분: 스프린트 자료
-- 근거: https://www.miryang.go.kr/hlt/index.do?mnNo=70600000000
insert into public.life_info (id, category, region_id, localized_content, address, phone, source_url, latitude, longitude, verified_at, is_published) values
('c1000000-0000-4000-8000-000000000021','hospital','a1000000-0000-4000-8000-000000001201',
 $nsd${"ko":{"name":"밀양병원","description":"밀양시보건소가 안내하는 응급의료기관입니다. 보건소 누리집에는 응급실을 24시간 운영한다고 적혀 있습니다(2026년 4월 기준)."},"en":{"name":"Miryang Hospital","description":"An emergency medical institution listed by the Miryang Public Health Center. The health center's website says its emergency room operates 24 hours (as of April 2026)."},"vi":{"name":"Bệnh viện Miryang (밀양병원)","description":"Đây là cơ sở y tế cấp cứu do Trung tâm y tế công cộng thành phố Miryang giới thiệu. Trang web của trung tâm y tế ghi rằng phòng cấp cứu hoạt động 24 giờ (tính đến tháng 4 năm 2026)."},"km":{"name":"មន្ទីរពេទ្យមីរយ៉ាង (밀양병원)","description":"ជាមន្ទីរពេទ្យសង្គ្រោះបន្ទាន់ដែលមណ្ឌលសុខភាពក្រុងមីរយ៉ាងបានណែនាំ។ គេហទំព័ររបស់មណ្ឌលសុខភាពសរសេរថា បន្ទប់សង្គ្រោះបន្ទាន់បើក 24 ម៉ោង (គិតត្រឹមខែ 4 ឆ្នាំ 2026)។"},"th":{"name":"โรงพยาบาลมีรยัง (밀양병원)","description":"เป็นสถานพยาบาลฉุกเฉินที่ศูนย์สาธารณสุขเมืองมีรยังแจ้งไว้ เว็บไซต์ของศูนย์สาธารณสุขเขียนว่าห้องฉุกเฉินเปิด 24 ชั่วโมง (ข้อมูลเดือนเมษายน 2026)"},"ne":{"name":"मिर्याङ अस्पताल (밀양병원)","description":"यो मिर्याङ सहर जनस्वास्थ्य केन्द्रले जानकारी दिएको आकस्मिक उपचार गर्ने अस्पताल हो। जनस्वास्थ्य केन्द्रको वेबसाइटमा आकस्मिक कक्ष 24 घण्टा चल्छ भनेर लेखिएको छ (2026 सालको अप्रिलअनुसार)।"},"mn":{"name":"Мирян эмнэлэг (밀양병원)","description":"Мирян хотын эрүүл мэндийн төвөөс зааж өгдөг яаралтай тусламжийн эмнэлэг юм. Эрүүл мэндийн төвийн вэб сайтад яаралтай тусламжийн тасаг 24 цаг ажилладаг гэж бичсэн байдаг (2026 оны 4-р сарын байдлаар)."},"uz":{"name":"Miryang kasalxonasi (밀양병원)","description":"Miryang shahar sogʻliqni saqlash markazi koʻrsatgan shoshilinch tibbiy yordam muassasasi. Markaz saytida shoshilinch yordam boʻlimi 24 soat ishlaydi deb yozilgan (2026-yil aprel holatiga koʻra)."},"ru":{"name":"Больница Мирян (밀양병원)","description":"Это больница скорой помощи, которую указывает Центр здоровья города Мирян. На сайте Центра здоровья написано, что отделение скорой помощи работает 24 часа (по данным на апрель 2026 года)."}}$nsd$::jsonb,
