insert into public.life_info (id, category, region_id, localized_content, address, phone, source_url, latitude, longitude, verified_at, is_published) values
('c1000000-0000-4000-8000-000000000022','hospital','a1000000-0000-4000-8000-000000001201',
 $nsd${"ko":{"name":"밀성메디칼약국","description":"밀양시보건소 약국 목록에 있는 약국입니다. 밤이나 휴일에 여는 약국은 응급의료포털(e-gen.or.kr)에서 찾을 수 있습니다."},"en":{"name":"Milseong Medical Pharmacy","description":"A pharmacy on the Miryang Public Health Center's pharmacy list. Pharmacies open at night or on holidays can be found on the Emergency Medical Portal (e-gen.or.kr)."},"vi":{"name":"Nhà thuốc Milseong Medical (밀성메디칼약국)","description":"Nhà thuốc này có trong danh sách nhà thuốc của Trung tâm y tế công cộng thành phố Miryang. Nhà thuốc mở cửa ban đêm hoặc ngày nghỉ có thể tìm trên Cổng thông tin y tế cấp cứu (e-gen.or.kr)."},"km":{"name":"ឱសថស្ថានមីលសុងមេឌីខល (밀성메디칼약국)","description":"ជាឱសថស្ថានដែលមានក្នុងបញ្ជីឱសថស្ថានរបស់មណ្ឌលសុខភាពក្រុងមីរយ៉ាង។ អ្នកអាចរកឱសថស្ថានដែលបើកពេលយប់ ឬថ្ងៃឈប់សម្រាក នៅលើគេហទំព័រសង្គ្រោះបន្ទាន់ (e-gen.or.kr)។"},"th":{"name":"ร้านขายยามิลซองเมดิคัล (밀성메디칼약국)","description":"เป็นร้านขายยาที่อยู่ในรายชื่อร้านขายยาของศูนย์สาธารณสุขเมืองมีรยัง ร้านขายยาที่เปิดตอนกลางคืนหรือวันหยุด หาได้ที่เว็บไซต์การแพทย์ฉุกเฉิน (e-gen.or.kr)"},"ne":{"name":"मिल्सङ मेडिकल औषधि पसल (밀성메디칼약국)","description":"यो मिर्याङ सहर जनस्वास्थ्य केन्द्रको औषधि पसलको सूचीमा भएको औषधि पसल हो। राति वा बिदाको दिन खुल्ने औषधि पसल आकस्मिक उपचार पोर्टल (e-gen.or.kr) मा खोज्न सकिन्छ।"},"mn":{"name":"Мильсон Медикал эмийн сан (밀성메디칼약국)","description":"Мирян хотын эрүүл мэндийн төвийн эмийн сангийн жагсаалтад байгаа эмийн сан юм. Шөнө эсвэл амралтын өдөр ажилладаг эмийн санг Яаралтай тусламжийн портал (e-gen.or.kr)-аас хайж болно."},"uz":{"name":"Milseong Medikal dorixonasi (밀성메디칼약국)","description":"Miryang shahar sogʻliqni saqlash markazining dorixonalar roʻyxatidagi dorixona. Kechasi yoki dam olish kunlari ishlaydigan dorixonalarni Shoshilinch tibbiy yordam portalidan (e-gen.or.kr) topish mumkin."},"ru":{"name":"Аптека «Мильсон Медикал» (밀성메디칼약국)","description":"Эта аптека есть в списке аптек Центра здоровья города Мирян. Аптеки, которые работают ночью или в выходные и праздники, можно найти на Портале скорой медицинской помощи (e-gen.or.kr)."}}$nsd$::jsonb,
