insert into public.life_info (id, category, region_id, localized_content, address, phone, source_url, latitude, longitude, verified_at, is_published) values
('c1000000-0000-4000-8000-000000000024','transport','a1000000-0000-4000-8000-000000001201',
 $nsd${"ko":{"name":"밀양역","description":"KTX가 서는 코레일 기차역입니다. 전화는 역이 아니라 철도고객센터 번호입니다."},"en":{"name":"Miryang Station","description":"A Korail train station where KTX trains stop. The phone number is the railway customer center, not the station itself."},"vi":{"name":"Ga tàu Miryang (밀양역)","description":"Đây là ga tàu của Korail, có tàu KTX dừng. Số điện thoại là số của Trung tâm khách hàng đường sắt, không phải số của ga."},"km":{"name":"ស្ថានីយរថភ្លើងមីរយ៉ាង (밀양역)","description":"ជាស្ថានីយរថភ្លើងរបស់ Korail ដែលរថភ្លើង KTX ឈប់។ លេខទូរស័ព្ទនេះមិនមែនជាលេខរបស់ស្ថានីយទេ គឺជាលេខមជ្ឈមណ្ឌលបម្រើអតិថិជនរថភ្លើង។"},"th":{"name":"สถานีรถไฟมีรยัง (밀양역)","description":"เป็นสถานีรถไฟของโคเรล (Korail) ที่รถไฟ KTX จอด เบอร์โทรนี้ไม่ใช่เบอร์ของสถานี แต่เป็นเบอร์ศูนย์บริการลูกค้ารถไฟ"},"ne":{"name":"मिर्याङ रेल स्टेसन (밀양역)","description":"यो KTX रेल रोकिने कोरेल (Korail) को रेल स्टेसन हो। फोन नम्बर स्टेसनको होइन, रेल ग्राहक केन्द्रको नम्बर हो।"},"mn":{"name":"Мирян галт тэрэгний буудал (밀양역)","description":"KTX галт тэрэг зогсдог Корэйл (Korail)-ийн галт тэрэгний буудал юм. Утасны дугаар нь буудлынх биш, төмөр замын үйлчлүүлэгчийн төвийн дугаар юм."},"uz":{"name":"Miryang temir yoʻl stansiyasi (밀양역)","description":"KTX poyezdi toʻxtaydigan Korail temir yoʻl stansiyasi. Telefon stansiyaniki emas, temir yoʻl mijozlar markazining raqami."},"ru":{"name":"Железнодорожный вокзал Мирян (밀양역)","description":"Это железнодорожный вокзал компании Korail, здесь останавливаются поезда KTX. Телефон — это номер Центра обслуживания клиентов железной дороги, а не самого вокзала."}}$nsd$::jsonb,
