-- M07 밀양버스터미널 [밀양시] 출처 구분: 공식 출처(밀양 기본 정보)
-- 근거: https://transportation.asamaru.net/시외버스/터미널/밀양시외버스터미널/ , https://www.miryang.go.kr/web/index.do?mnNo=50302000000
insert into public.life_info (id, category, region_id, localized_content, address, phone, source_url, latitude, longitude, verified_at, is_published) values
('c1000000-0000-4000-8000-000000000025','transport','a1000000-0000-4000-8000-000000001201',
 $nsd${"ko":{"name":"밀양버스터미널","description":"시외버스 터미널입니다. 밀양시는 시외버스 시간 문의처로 밀성여객 055-354-6107을 안내합니다."},"en":{"name":"Miryang Bus Terminal","description":"The intercity bus terminal. For intercity bus times, Miryang City refers people to the bus company Milseong Yeogaek, 055-354-6107."},"vi":{"name":"Bến xe buýt Miryang (밀양버스터미널)","description":"Đây là bến xe buýt liên tỉnh. Thành phố Miryang hướng dẫn hỏi giờ xe buýt liên tỉnh ở công ty xe khách Milseong Yeogaek (밀성여객), số 055-354-6107."},"km":{"name":"ចំណតឡានក្រុងមីរយ៉ាង (밀양버스터미널)","description":"ជាចំណតឡានក្រុងទៅក្រុងផ្សេង។ បើចង់សួរម៉ោងឡានក្រុងទៅក្រុងផ្សេង ក្រុងមីរយ៉ាងប្រាប់ឱ្យទាក់ទងក្រុមហ៊ុនឡានក្រុង មីលសុងយគែក (밀성여객) 055-354-6107។"},"th":{"name":"สถานีขนส่งมีรยัง (밀양버스터미널)","description":"เป็นสถานีรถบัสระหว่างเมือง เมืองมีรยังแจ้งว่าถามเวลารถบัสระหว่างเมืองได้ที่มิลซองยอแกก (밀성여객) 055-354-6107"},"ne":{"name":"मिर्याङ बस टर्मिनल (밀양버스터미널)","description":"यो अर्को सहर जाने बसको टर्मिनल हो। अर्को सहर जाने बसको समय सोध्ने ठाउँको रूपमा मिर्याङ सहरले मिल्सङ योगेक (밀성여객) 055-354-6107 बताउँछ।"},"mn":{"name":"Мирян автобусны буудал (밀양버스터미널)","description":"Хот хоорондын автобусны буудал юм. Хот хоорондын автобусны цагийг асуух газар гэж Мирян хотын захиргаа Мильсон Ёгэг (밀성여객) 055-354-6107 дугаарыг зааж өгдөг."},"uz":{"name":"Miryang avtovokzali (밀양버스터미널)","description":"Shaharlararo avtobuslar avtovokzali. Miryang shahri shaharlararo avtobus vaqtlarini soʻrash uchun Milseong Yeogaek (밀성여객) 055-354-6107 raqamini koʻrsatadi."},"ru":{"name":"Автовокзал Мирян (밀양버스터미널)","description":"Это вокзал междугородних автобусов. Чтобы узнать расписание междугородних автобусов, город Мирян советует звонить в компанию «Мильсон Ёгэк» (밀성여객): 055-354-6107."}}$nsd$::jsonb,
