insert into public.life_info (id, category, region_id, localized_content, address, phone, source_url, latitude, longitude, verified_at, is_published) values
('c1000000-0000-4000-8000-000000000026','market','a1000000-0000-4000-8000-000000001201',
 $nsd${"ko":{"name":"밀양아리랑시장","description":"밀양 시내의 전통시장입니다. 장날은 날짜 끝자리가 2와 7인 날입니다."},"en":{"name":"Miryang Arirang Market","description":"A traditional market in downtown Miryang. Market days are dates ending in 2 and 7."},"vi":{"name":"Chợ Miryang Arirang (밀양아리랑시장)","description":"Đây là chợ truyền thống ở trung tâm thành phố Miryang. Ngày họp chợ là những ngày có số cuối là 2 và 7."},"km":{"name":"ផ្សារមីរយ៉ាងអារីរ៉ាង (밀양아리랑시장)","description":"ជាផ្សារប្រពៃណីនៅកណ្តាលក្រុងមីរយ៉ាង។ ថ្ងៃផ្សារគឺថ្ងៃទីដែលមានលេខចុងក្រោយ 2 និង 7។"},"th":{"name":"ตลาดมีรยังอารีรัง (밀양아리랑시장)","description":"เป็นตลาดพื้นบ้านในตัวเมืองมีรยัง วันตลาดนัดคือวันที่ลงท้ายด้วยเลข 2 และ 7"},"ne":{"name":"मिर्याङ आरिराङ बजार (밀양아리랑시장)","description":"यो मिर्याङ सहरको बीच भागमा रहेको परम्परागत बजार हो। हाट लाग्ने दिन मितिको अन्तिम अङ्क 2 र 7 भएका दिन हुन्।"},"mn":{"name":"Мирян Ариран зах (밀양아리랑시장)","description":"Мирян хотын төвд байдаг уламжлалт зах юм. Зах гардаг өдөр нь сарын өдрийн сүүлийн тоо 2 ба 7 байх өдрүүд."},"uz":{"name":"Miryang Arirang bozori (밀양아리랑시장)","description":"Miryang shahar markazidagi anʼanaviy bozor. Bozor kunlari — sananing oxirgi raqami 2 va 7 boʻlgan kunlar."},"ru":{"name":"Рынок Мирян Ариран (밀양아리랑시장)","description":"Это традиционный рынок в центре города Мирян. Базарные дни — числа месяца, которые заканчиваются на 2 и 7."}}$nsd$::jsonb,
