insert into public.life_info (id, category, region_id, localized_content, address, phone, source_url, latitude, longitude, verified_at, is_published) values
('c1000000-0000-4000-8000-000000000027','market','a1000000-0000-4000-8000-000000001201',
 $nsd${"ko":{"name":"수산시장 · 하남읍","description":"하남읍 수산리의 전통시장입니다. 장날은 날짜 끝자리가 3과 8인 날입니다. 농산물, 수산물, 생활용품을 팝니다."},"en":{"name":"Susan Market · Hanam-eup","description":"A traditional market in Susan-ri, Hanam-eup. Market days are dates ending in 3 and 8. Sells farm produce, seafood and household goods."},"vi":{"name":"Chợ Susan · thị trấn Hanam (수산시장 · 하남읍)","description":"Đây là chợ truyền thống ở Susan-ri (수산리), thị trấn Hanam (하남읍). Ngày họp chợ là những ngày có số cuối là 3 và 8. Chợ bán nông sản, thủy sản, đồ dùng hằng ngày."},"km":{"name":"ផ្សារស៊ូសាន · ទីប្រជុំជនហាណាម (수산시장 · 하남읍)","description":"ជាផ្សារប្រពៃណីនៅភូមិស៊ូសាន (수산리) ទីប្រជុំជនហាណាម (하남읍)។ ថ្ងៃផ្សារគឺថ្ងៃទីដែលមានលេខចុងក្រោយ 3 និង 8។ លក់កសិផល គ្រឿងសមុទ្រ និងរបស់ប្រើប្រាស់ប្រចាំថ្ងៃ។"},"th":{"name":"ตลาดซูซาน · ตำบลฮานัม (수산시장 · 하남읍)","description":"เป็นตลาดพื้นบ้านที่หมู่บ้านซูซาน (수산리) ตำบลฮานัม (하남읍) วันตลาดนัดคือวันที่ลงท้ายด้วยเลข 3 และ 8 ขายผักผลไม้ อาหารทะเล และของใช้ในบ้าน"},"ne":{"name":"सुसान बजार · हानाम-उप (수산시장 · 하남읍)","description":"यो हानाम-उप (하남읍) को सुसान-री (수산리) मा रहेको परम्परागत बजार हो। हाट लाग्ने दिन मितिको अन्तिम अङ्क 3 र 8 भएका दिन हुन्। यहाँ कृषि उपज, समुद्री उपज र घरायसी सामान बेचिन्छ।"},"mn":{"name":"Сүсан зах · Ханам суурин (수산시장 · 하남읍)","description":"Ханам суурин (하남읍)-ы Сүсан тосгон (수산리)-д байдаг уламжлалт зах юм. Зах гардаг өдөр нь сарын өдрийн сүүлийн тоо 3 ба 8 байх өдрүүд. Газар тариалангийн бүтээгдэхүүн, далайн бүтээгдэхүүн, ахуйн бараа зардаг."},"uz":{"name":"Susan bozori · Hanam shaharchasi (수산시장 · 하남읍)","description":"Hanam shaharchasi (하남읍) Susan-ri (수산리) qishlogʻidagi anʼanaviy bozor. Bozor kunlari — sananing oxirgi raqami 3 va 8 boʻlgan kunlar. Qishloq xoʻjaligi mahsulotlari, dengiz mahsulotlari va roʻzgʻor buyumlari sotiladi."},"ru":{"name":"Рынок Сусан · посёлок Ханам (수산시장 · 하남읍)","description":"Это традиционный рынок в деревне Сусан-ни (수산리), посёлок Ханам (하남읍). Базарные дни — числа месяца, которые заканчиваются на 3 и 8. Здесь продают овощи и фрукты, рыбу и морепродукты, товары для дома."}}$nsd$::jsonb,
