-- M10 아시아마트 · 내이동 [밀양시] 출처 구분: 지도 조사로 보완
-- 근거: https://bizno.net/article/6151776294
insert into public.life_info (id, category, region_id, localized_content, address, phone, source_url, latitude, longitude, verified_at, is_published) values
('c1000000-0000-4000-8000-000000000028','market','a1000000-0000-4000-8000-000000001201',
 $nsd${"ko":{"name":"아시아마트 · 내이동","description":"이름이 '아시아마트'인 가게입니다. 지도에는 슈퍼마켓으로 등록돼 있습니다. 어느 나라 식품을 파는지는 확인하지 못했습니다. 전화번호는 아래 출처(지도)에서 확인하세요."},"en":{"name":"Asia Mart · Naei-dong","description":"A shop named 'Asia Mart'. It is listed on the map as a supermarket. We could not confirm which countries' foods it sells. For the phone number, check the map page under Source below."},"vi":{"name":"Cửa hàng Asia Mart · phường Naei (아시아마트 · 내이동)","description":"Đây là cửa hàng có tên 'Asia Mart'. Trên bản đồ, cửa hàng được đăng ký là siêu thị. Chúng tôi chưa xác nhận được cửa hàng bán thực phẩm của nước nào. Số điện thoại xin xem ở phần nguồn (bản đồ) bên dưới."},"km":{"name":"អាស៊ីម៉ាត · សង្កាត់ណែអ៊ី (아시아마트 · 내이동)","description":"ជាហាងដែលមានឈ្មោះថា «អាស៊ីម៉ាត» (아시아마트)។ នៅលើផែនទី ហាងនេះចុះឈ្មោះជាផ្សារទំនើប។ យើងមិនទាន់បានបញ្ជាក់ថាហាងលក់អាហាររបស់ប្រទេសណាទេ។ សូមមើលលេខទូរស័ព្ទនៅក្នុងប្រភព (ផែនទី) ខាងក្រោម។"},"th":{"name":"เอเชียมาร์ท · ย่านแนอีดง (아시아마트 · 내이동)","description":"เป็นร้านที่ชื่อว่า 'เอเชียมาร์ท' ในแผนที่ลงทะเบียนเป็นซูเปอร์มาร์เก็ต เรายังตรวจสอบไม่ได้ว่าขายอาหารของประเทศไหน ดูเบอร์โทรได้ที่แหล่งข้อมูล (แผนที่) ด้านล่าง"},"ne":{"name":"एसिया मार्ट · नेइ-दोङ (아시아마트 · 내이동)","description":"यो 'एसिया मार्ट' नाम भएको पसल हो। नक्सामा यो सुपरमार्केटको रूपमा दर्ता छ। यहाँ कुन देशको खाद्य सामग्री बेचिन्छ, हामीले पक्का गर्न सकेनौँ। फोन नम्बर तलको स्रोत (नक्सा) मा हेर्नुहोस्।"},"mn":{"name":"Ази Март · Нэи хороо (아시아마트 · 내이동)","description":"«Ази Март» гэдэг нэртэй дэлгүүр юм. Газрын зураг дээр супермаркет гэж бүртгэгдсэн. Аль орны хүнс зардгийг шалгаж чадаагүй. Утасны дугаарыг доорх эх сурвалж (газрын зураг)-аас харна уу."},"uz":{"name":"Asia Mart · Naei mahallasi (아시아마트 · 내이동)","description":"Nomi «Asia Mart» boʻlgan doʻkon. Xaritada supermarket sifatida roʻyxatga olingan. Qaysi mamlakat oziq-ovqatlarini sotishini aniqlay olmadik. Telefon raqamini pastdagi manbadan (xarita) koʻring."},"ru":{"name":"Азия Март · район Нэи-дон (아시아마트 · 내이동)","description":"Это магазин с назван