-- M16 우즈베키스탄식당 [밀양시] 출처 구분: 스프린트 자료
-- 근거: https://www.diningcode.com/profile.php?rid=pMOAypYnODGn
insert into public.life_info (id, category, region_id, localized_content, address, phone, source_url, latitude, longitude, verified_at, is_published) values
('c1000000-0000-4000-8000-000000000034','other','a1000000-0000-4000-8000-000000001201',
 $nsd${"ko":{"name":"우즈베키스탄식당","description":"우즈베키스탄·러시아 음식점으로 분류된 식당입니다. 메뉴는 확인하지 못했습니다."},"en":{"name":"Uzbekistan Restaurant","description":"A restaurant classified as Uzbek and Russian cuisine. We could not confirm the menu."},"vi":{"name":"Quán ăn Uzbekistan (우즈베키스탄식당)","description":"Quán này được phân loại là quán ăn Uzbekistan và Nga. Chúng tôi chưa xác nhận được thực đơn."},"km":{"name":"ភោជនីយដ្ឋានអ៊ូសបេគីស្ថាន (우즈베키스탄식당)","description":"ជាភោជនីយដ្ឋានដែលគេចាត់ថ្នាក់ជាភោជនីយដ្ឋានម្ហូបអ៊ូសបេគីស្ថាន និងរុស្ស៊ី។ យើងមិនទាន់បានបញ្ជាក់មុខម្ហូបទេ។"},"th":{"name":"ร้านอาหารอุซเบกิสถาน (우즈베키스탄식당)","description":"เป็นร้านที่จัดอยู่ในประเภทร้านอาหารอุซเบกิสถานและรัสเซีย เรายังตรวจสอบเมนูไม่ได้"},"ne":{"name":"उज्बेकिस्तान रेस्टुरेन्ट (우즈베키스탄식당)","description":"यो उज्बेकिस्तानी र रूसी खानाको रेस्टुरेन्ट भनेर वर्गीकरण गरिएको रेस्टुरेन्ट हो। मेनु हामीले पक्का गर्न सकेनौँ।"},"mn":{"name":"Узбекистан хоолны газар (우즈베키스탄식당)","description":"Узбекистан, Орос хоолны газар гэж ангилагдсан хоолны газар юм. Хоолны цэсийг шалгаж чадаагүй."},"uz":{"name":"Oʻzbekiston taomxonasi (우즈베키스탄식당)","description":"Oʻzbekiston va Rossiya taomlari taomxonasi deb tasniflangan joy. Menyusini aniqlay olmadik."},"ru":{"name":"Кафе «Узбекистан» (우즈베키스탄식당)","description":"Это заведение записано как кафе узбекской и русской кухни. Меню мы не смогли проверить."}}$nsd$::jsonb,
