-- M17 밀양시가족센터 [밀양시] 출처 구분: 스프린트 자료
-- 근거: https://miryang.familynet.or.kr/center/index.do
insert into public.life_info (id, category, region_id, localized_content, address, phone, source_url, latitude, longitude, verified_at, is_published) values
('c1000000-0000-4000-8000-000000000035','support','a1000000-0000-4000-8000-000000001201',
 $nsd${"ko":{"name":"밀양시가족센터","description":"밀양시의 가족센터입니다. 가곡동 상상어울림센터 3층에 있습니다. 통역 서비스가 있는지, 외국인 근로자가 이용할 수 있는지는 확인하지 못했습니다. 전화로 물어보세요."},"en":{"name":"Miryang Family Center","description":"Miryang City's family center, on the 3rd floor of the Sangsang Eoullim Center in Gagok-dong. We could not confirm whether it offers interpretation or whether foreign workers can use its services. Please ask by phone."},"vi":{"name":"Trung tâm gia đình thành phố Miryang (밀양시가족센터)","description":"Đây là trung tâm gia đình của thành phố Miryang. Trung tâm ở tầng 3 tòa nhà Sangsang Eoullim Center (상상어울림센터), phường Gagok (가곡동). Chúng tôi chưa xác nhận được ở đây có dịch vụ phiên dịch hay không, và lao động nước ngoài có dùng được hay không. Bạn hãy gọi điện để hỏi."},"km":{"name":"មជ្ឈមណ្ឌលគ្រួសារក្រុងមីរយ៉ាង (밀양시가족센터)","description":"ជាមជ្ឈមណ្ឌលគ្រួសាររបស់ក្រុងមីរយ៉ាង។ នៅជាន់ទី 3 នៃមជ្ឈមណ្ឌលសាងសាងអូអ៊ុលលីម (상상어울림센터) សង្កាត់កាគក់ (가곡동)។ យើងមិនទាន់បានបញ្ជាក់ថាមានសេវាបកប្រែឬអត់ និងថាពលករបរទេសអាចប្រើបានឬអត់ទេ។ សូមសួរតាមទូរស័ព្ទ។"},"th":{"name":"ศูนย์ครอบครัวเมืองมีรยัง (밀양시가족센터)","description":"เป็นศูนย์ครอบครัวของเมืองมีรยัง อยู่ชั้น 3 ของศูนย์ซังซังอออุลลิม (상상어울림센터) ย่านคากกดง (가곡동) เรายังตรวจสอบไม่ได้ว่ามีบริการล่ามหรือไม่ และแรงงานต่างชาติใช้บริการได้หรือไม่ ให้โทรไปถาม"},"ne":{"name":"मिर्याङ सहर परिवार केन्द्र (밀양시가족센터)","description":"यो मिर्याङ सहरको परिवार केन्द्र हो। यो गागोक-दोङ (가곡동) को साङसाङ ओउल्लिम सेन्टर (상상어울림센터) को 3 तलामा छ। दोभासे सेवा छ कि छैन र विदेशी कामदारले यो केन्द्र प्रयोग गर्न पाउँछन् कि पाउँदैनन्, हामीले पक्का गर्न सकेनौँ। फोन गरेर सोध्नुहोस्।"},"mn":{"name":"Мирян хотын гэр бүлийн төв (밀양시가족센터)","description":"Мирян хотын гэр бүлийн төв юм. Гагок хороо (가곡동)-ны Сансан Оуллим төв (상상어울림센터)-ийн 3 давхарт байдаг. Орчуулгын үйлчилгээ байгаа эсэх, гадаад ажилчид үйлчлүүлж болох эсэхийг шалгаж чадаагүй. Утсаар асуугаарай."},"uz":{"name":"Miryang shahar oila markazi (밀양시가족센터)","description":"Miryang shahrining oila markazi. Gagok mahallasidagi (가곡동) Sangsang Oullim markazining (상상어울림센터) 3-qavatida joylashgan. Tarjima xizmati bor-yoʻqligini va chet ellik ishchilar foydalana olish-olmasligini aniqlay olmadik. Telefon orqali soʻrang."},"ru":{"name":"Семейный центр города Мирян (밀양시가족센터)","description":"Это семейный центр города Мирян. Он находится на 3 этаже центра «Сансан Оуллим» (상상어울림센터) в районе Кагок-дон (가곡동). Есть ли здесь услуги переводчика и могут ли сюда обращаться иностранные работники, мы не смогли проверить. Спросите по телефону."}}$nsd$::jsonb,
 $nsd$경남 밀양시 가곡6길 8 상상어울림센터 3층$nsd$,$nsd$055-351-4404$nsd$,$nsd$https://miryang.familynet.or.kr/center/index.do$nsd$,35.475879,128.767803,'2026-10-13',true)
on conflict (id) do nothing;

-- M18 양산외국인노동자의집 [밀양시] 출처 구분: 스프린트 자료
-- 근거: https://withmigrant.or.kr/intro
insert into public.life_info (id, category, region_id, localized_content, address, phone, source_url, latitude, longitude, verified_at, is_published) values
('c1000000-0000-4000-8000-000000000036','support','a1000000-0000-4000-8000-000000001201',
 $nsd${"ko":{"name":"양산외국인노동자의집","description":"밀양이 아니라 양산시에 있는 민간 단체입니다. 누리집 안내로는 이주민 인권 상담, 한글교실, 무료진료소를 운영합니다. 2022년 4월에 올린 활동 기록에 밀양 농장에서 일하던 노동자를 상담한 사례가 있습니다. 주소는 경남 양산시 북안북7길 35 양산시근로자종합복지관 1층입니다."},"en":{"name":"Yangsan House for Migrant Workers","description":"A private organization located in Yangsan City, not in Miryang. According to its website it offers human-rights counseling for migrants, Korean classes and a free clinic. An activity record it posted in April 2022 describes a case in which it counseled workers from a farm in Miryang. Address: 35 Bugan-buk 7-gil, Yangsan-si, Gyeongnam, 1st floor of the Yangsan Workers' Welfare Center."},"vi":{"name":"Nhà của lao động nước ngoài Yangsan (양산외국인노동자의집)","description":"Đây là tổ chức tư nhân ở thành phố Yangsan, không phải ở Miryang. Theo trang web, nơi này có tư vấn nhân quyền cho người di cư, lớp học chữ Hàn và phòng khám miễn phí. Trong ghi chép hoạt động đăng vào tháng 4 năm 2022 có trường hợp nơi này tư vấn cho lao động làm việc ở nông trại tại Miryang. Địa chỉ: tầng 1 Trung tâm phúc lợi tổng hợp người lao động thành phố Yangsan (양산시근로자종합복지관), 35 Bugan-buk 7-gil (북안북7길 35), thành phố Yangsan (양산시), tỉnh Gyeongnam (경남)."},"km":{"name":"ផ្ទះពលករបរទេសយ៉ាងសាន (양산외국인노동자의집)","description":"ជាអង្គការឯកជនដែលនៅក្រុងយ៉ាងសាន មិនមែននៅមីរយ៉ាងទេ។ តាមគេហទំព័រ អង្គការនេះមានការប្រឹក្សាសិទ្ធិមនុស្សសម្រាប់ជនចំណាកស្រុក ថ្នាក់រៀនអក្សរកូរ៉េ និងកន្លែងព្យាបាលឥតគិតថ្លៃ។ ក្នុងកំណត់ត្រាសកម្មភាពដែលបានចុះផ្សាយនៅខែ 4 ឆ្នាំ 2022 មានករណីដែលអង្គការនេះបានប្រឹក្សាជូនពលករដែលធ្វើការនៅកសិដ្ឋានក្នុងមីរយ៉ាង។ អាសយដ្ឋានគឺ ជាន់ទី 1 មជ្ឈមណ្ឌលសុខុមាលភាពកម្មករក្រុងយ៉ាងសាន (양산시근로자종합복지관) ផ្លូវប៊ូកានប៊ុក 7-គីល លេខ 35 (북안북7길 35) ក្រុងយ៉ាងសាន ខេត្តគ្យងណាម។"},"th":{"name":"บ้านแรงงานต่างชาติยังซาน (양산외국인노동자의집)","description":"เป็นองค์กรเอกชนที่อยู่ในเมืองยังซาน ไม่ได้อยู่ในมีรยัง เว็บไซต์ขององค์กรบอกว่ามีการให้คำปรึกษาเรื่องสิทธิมนุษยชนของผู้ย้ายถิ่น ห้องเรียนภาษาเกาหลี และคลินิกรักษาฟรี ในบันทึกกิจกรรมที่ลงไว้เมื่อเดือนเมษายน 2022 มีกรณีที่ให้คำปรึกษาแรงงานที่ทำงานในฟาร์มที่มีรยัง ที่อยู่คือ ชั้น 1 อาคารสวัสดิการแรงงานเมืองยังซาน (양산시근로자종합복지관) เลขที่ 35 ถนนพูกันบุก 7-กิล เมืองยังซาน จังหวัดคยองนัม (경남 양산시 북안북7길 35)"},"ne":{"name":"याङसान विदेशी कामदारको घर (양산외국인노동자의집)","description":"यो मिर्याङमा होइन, याङसान सहरमा रहेको निजी संस्था हो। वेबसाइटको जानकारीअनुसार यसले आप्रवासीको मानव अधिकार परामर्श, कोरियन अक्षर (हान्गुल) कक्षा र निःशुल्क उपचार केन्द्र चलाउँछ। 2022 सालको अप्रिलमा राखिएको गतिविधिको रेकर्डमा मिर्याङको खेतमा काम गर्ने कामदारलाई परामर्श दिएको घटना छ। ठेगाना: ग्योङनाम याङसान सहर बुगानबुक 7-गिल 35 (경남 양산시 북안북7길 35), याङसान सहर श्रमिक समग्र कल्याण भवन (양산시근로자종합복지관) को 1 तला।"},"mn":{"name":"Янсан гадаад ажилчдын гэр (양산외국인노동자의집)","description":"Мирянд биш, Янсан хотод байдаг төрийн бус байгууллага юм. Вэб сайтад бичсэнээр цагаачдад хүний эрхийн зөвлөгөө өгдөг, солонгос үсгийн анги, үнэгүй эмчилгээний газар ажиллуулдаг. 2022 оны 4-р сард тавьсан үйл ажиллагааны тэмдэглэлд Мирянгийн фермд ажиллаж байсан ажилчдад зөвлөгөө өгсөн тохиолдол бий. Хаяг: Өмнөд Гёнсан муж, Янсан хот, Бүган-бүк 7-гиль 35 (경남 양산시 북안북7길 35), Янсан хотын ажилчдын халамжийн төв (양산시근로자종합복지관)-ийн 1 давхар."},"uz":{"name":"Yangsan chet ellik ishchilar uyi (양산외국인노동자의집)","description":"Miryangda emas, Yangsan shahrida joylashgan nodavlat tashkilot. Saytidagi maʼlumotga koʻra, muhojirlarning inson huquqlari boʻyicha maslahat, koreys yozuvi (hangul) darslari va bepul tibbiy punkt ishlaydi. 2022-yil aprel oyida joylangan faoliyat yozuvlarida Miryangdagi fermada ishlagan ishchilarga maslahat berilgani haqida misol bor. Manzil: Gyeongnam, Yangsan shahri, Bugan-buk 7-gil 35 (경남 양산시 북안북7길 35), Yangsan shahar ishchilar farovonlik markazining (양산시근로자종합복지관) 1-qavati."},"ru":{"name":"Дом иностранных рабочих в Янсане (양산외국인노동자의집)","description":"Это негосударственная организация. Она находится не в Миряне, а в городе Янсан. По информации на сайте, здесь консультируют мигрантов по защите их прав, есть уроки корейского языка и бесплатный медицинский кабинет. В записи о своей работе, которую организация разместила в апреле 2022 года, есть случай: здесь консультировали рабочих, которые работали на ферме в Миряне. Адрес: провинция Кённам, город Янсан, улица Пуган-пук 7-гиль, 35, Центр социальной поддержки рабочих города Янсан, 1 этаж (경남 양산시 북안북7길 35 양산시근로자종합복지관 1층)."}}$nsd$::jsonb,
 null,$nsd$055-388-0988$nsd$,$nsd$https://withmigrant.or.kr/intro$nsd$,null,null,'2026-10-13',true)
on conflict (id) do nothing;

-- M19 외국인력상담센터 ☎1577-0071 [밀양시] 출처 구분: 공식 출처(상담전화)
