-- M20 경상남도 외국인주민지원센터 ☎055-237-8779 [밀양시] 출처 구분: 공식 출처(상담전화)
-- 근거: https://www.changwon.go.kr/cwportal/depart/11061/14440/14445.web , https://www.gnmigrant.or.kr/sub_02_01.htm
insert into public.life_info (id, category, region_id, localized_content, address, phone, source_url, latitude, longitude, verified_at, is_published) values
('c1000000-0000-4000-8000-000000000038','support','a1000000-0000-4000-8000-000000001201',
 $nsd${"ko":{"name":"경상남도 외국인주민지원센터 ☎055-237-8779","description":"경상남도가 세운 외국인 주민 지원 센터입니다. 밀양이 아니라 창원시에 있습니다. 일터, 고용허가제, 출입국, 생활 문제를 상담합니다. 월~금 09:00~18:00, 일요일 13:00~18:00에 받고 토요일은 쉽니다. 베트남어, 캄보디아어, 태국어, 네팔어, 몽골어 상담은 요일에 따라 됩니다. 우즈베크어와 러시아어는 안내에 없습니다."},"en":{"name":"Gyeongnam Support Center for Foreign Residents ☎055-237-8779","description":"A support center for foreign residents set up by Gyeongsangnam-do Province. It is located in Changwon City, not in Miryang. Counseling on work, the Employment Permit System, immigration and daily-life problems. Open Mon–Fri 09:00–18:00 and Sunday 13:00–18:00; closed on Saturdays. Vietnamese, Khmer, Thai, Nepali and Mongolian counseling is available on certain days. Uzbek and Russian are not listed."},"vi":{"name":"Trung tâm hỗ trợ người nước ngoài tỉnh Gyeongnam ☎055-237-8779 (경상남도 외국인주민지원센터)","description":"Đây là trung tâm hỗ trợ người nước ngoài do tỉnh Gyeongsangnam (경상남도) lập ra. Trung tâm ở thành phố Changwon, không phải ở Miryang. Trung tâm tư vấn về nơi làm việc, chế độ cấp phép lao động (EPS), xuất nhập cảnh và các vấn đề đời sống. Nhận cuộc gọi thứ Hai~thứ Sáu 09:00~18:00, Chủ nhật 13:00~18:00, nghỉ thứ Bảy. Tư vấn bằng tiếng Việt, tiếng Campuchia, tiếng Thái, tiếng Nepal, tiếng Mông Cổ thì tùy theo ngày trong tuần. Tiếng Uzbek và tiếng Nga không có trong thông báo."},"km":{"name":"មជ្ឈមណ្ឌលជួយជនបរទេស ខេត្តគ្យងសាងណាម ☎055-237-8779 (경상남도 외국인주민지원센터)","description":"ជាមជ្ឈមណ្ឌលជួយជនបរទេស ដែលខេត្តគ្យងសាងណាមបានបង្កើត។ នៅក្រុងឆាងវ៉ុន មិនមែននៅមីរយ៉ាងទេ។ ប្រឹក្សាអំពីកន្លែងធ្វើការ ប្រព័ន្ធអនុញ្ញាតការងារ ការចូលចេញប្រទេស និងបញ្ហាការរស់នៅ។ ទទួលប្រឹក្សាថ្ងៃច័ន្ទ~សុក្រ ម៉ោង 09:00~18:00 និងថ្ងៃអាទិត្យ ម៉ោង 13:00~18:00 ហើយឈប់ថ្ងៃសៅរ៍។ ការប្រឹក្សាជាភាសាវៀតណាម ខ្មែរ ថៃ នេប៉ាល់ និងម៉ុងហ្គោលី មានតែថ្ងៃខ្លះក្នុងសប្តាហ៍។ ភាសាអ៊ូសបេគីស្ថាន និងរុស្ស៊ី មិនមានក្នុងសេចក្តីជូនដំណឹងទេ។"},"th":{"name":"ศูนย์ช่วยเหลือชาวต่างชาติ จังหวัดคยองซังนัม ☎055-237-8779 (경상남도 외국인주민지원센터)","description":"เป็นศูนย์ช่วยเหลือชาวต่างชาติที่จังหวัดคยองซังนัมตั้งขึ้น ไม่ได้อยู่ในมีรยัง แต่อยู่ที่เมืองชางวอน ให้คำปรึกษาเรื่องที่ทำงาน ระบบใบอนุญาตจ้างงาน (EPS) การตรวจคนเข้าเมือง และปัญหาการใช้ชีวิต รับสายวันจันทร์~ศุกร์ 09:00~18:00 วันอาทิตย์ 13:00~18:00 หยุดวันเสาร์ การให้คำปรึกษาเป็นภาษาเวียดนาม ภาษาเขมร ภาษาไทย ภาษาเนปาล และภาษามองโกเลีย มีเฉพาะบางวันในสัปดาห์ ภาษาอุซเบกและภาษารัสเซียไม่มีในประกาศ"},"ne":{"name":"ग्योङसाङनाम-दो विदेशी बासिन्दा सहायता केन्द्र ☎055-237-8779 (경상남도 외국인주민지원센터)","description":"यो ग्योङसाङनाम-दो प्रदेशले खोलेको विदेशी बासिन्दा सहायता केन्द्र हो। यो मिर्याङमा होइन, छाङवन सहरमा छ। काम गर्ने ठाउँ, रोजगार अनुमति प्रणाली (EPS), अध्यागमन र दैनिक जीवनका समस्याबारे परामर्श हुन्छ। सोमबार~शुक्रबार 09:00~18:00, आइतबार 13:00~18:00 सम्म फोन उठाइन्छ, शनिबार बन्द हुन्छ। भियतनामी, खमेर, थाई, नेपाली र मङ्गोलियन भाषाको परामर्श बारअनुसार मात्र हुन्छ। उज्बेक र रूसी भाषा जानकारीमा छैन।"},"mn":{"name":"Өмнөд Гёнсан мужийн гадаад иргэдийг дэмжих төв ☎055-237-8779 (경상남도 외국인주민지원센터)","description":"Өмнөд Гёнсан мужийн байгуулсан гадаад иргэдийг дэмжих төв юм. Мирянд биш, Чанвон хотод байдаг. Ажлын байр, хөдөлмөр эрхлэх зөвшөөрлийн тогтолцоо (고용허가제), цагаачлал, амьдралын асуудлаар зөвлөгөө өгнө. Даваа~Баасан 09:00~18:00, Ням гараг 13:00~18:00 цагт утас авна, Бямба гараг амарна. Вьетнам, камбож, тайланд, непал, монгол хэлний зөвлөгөө гарагаас хамаарч боломжтой. Узбек, орос хэл мэдээлэлд байхгүй."},"uz":{"name":"Gyeongsangnam-do chet ellik aholiga yordam markazi ☎055-237-8779 (경상남도 외국인주민지원센터)","description":"Gyeongsangnam-do viloyati tashkil qilgan chet ellik aholiga yordam markazi. Miryangda emas, Changwon shahrida joylashgan. Ish joyi, ishga ruxsat berish tizimi, kirish-chiqish (migratsiya) va kundalik hayot muammolari boʻyicha maslahat beradi. Dushanbadan jumagacha 09:00~18:00, yakshanba 13:00~18:00 da qabul qiladi, shanba kuni dam oladi. Vyetnam, kambodja (kxmer), tay, nepal va moʻgʻul tillarida maslahat hafta kuniga qarab boʻladi. Oʻzbek va rus tillari maʼlumotda koʻrsatilmagan."},"ru":{"name":"Центр поддержки иностранцев провинции Кёнсан-Намдо ☎055-237-8779 (경상남도 외국인주민지원센터)","description":"Это центр поддержки иностранных жителей, который создала провинция Кёнсан-Намдо. Он находится не в Миряне, а в городе Чханвон. Здесь консультируют по вопросам работы, системы разрешений на работу, виз и пребывания, повседневной жизни. Звонки принимают с понедельника по пятницу 09:00~18:00 и в воскресенье 13:00~18:00, в субботу выходной. Консультации на вьетнамском, кхмерском, тайском, непальском и монгольском языках — в определённые дни недели. Узбекского и русского языков в объявлении нет."}}$nsd$::jsonb,
 null,$nsd$055-237-8779$nsd$,$nsd$https://www.gnmigrant.or.kr/sub_02_01.htm$nsd$,null,null,'2026-10-13',true)
