-- M21 나라별 안내: 음식점·식재료·모국어 상담 [밀양시] 출처 구분: 위 항목들의 요약(나라별 질답)
insert into public.life_info (id, category, region_id, localized_content, address, phone, source_url, latitude, longitude, verified_at, is_published) values
('c1000000-0000-4000-8000-000000000039','support','a1000000-0000-4000-8000-000000001201',
 $nsd${"ko":{"name":"나라별 안내: 음식점·식재료·모국어 상담","description":"2026년 10월에 확인한 내용입니다.\n베트남: 음식점 4곳 — 월남국수, 쌀국수플러스, 하노이쌀국수(시내), 하노이퍼(하남읍).\n우즈베키스탄: 하남읍에 우즈베키스탄식당이 있습니다.\n태국, 네팔, 몽골, 캄보디아: 이 나라 음식점은 찾지 못했습니다.\n식재료: '아시아마트'라는 이름의 가게 가운데 주소를 확인한 내이동 1곳과 하남읍 1곳을 실었습니다. 파는 물건은 가서 확인하세요.\n모국어 상담 전화 1577-0071: 베트남어, 태국어, 캄보디아어, 네팔어, 몽골어, 우즈베크어. 365일 09:00~18:00.\n모국어 상담 전화 1345: 러시아어 등 20개 언어(우즈베크어는 안내에 없습니다). 평일 09:00~22:00, 18:00 이후는 한국어, 영어, 중국어만 됩니다."},"en":{"name":"Guide by country: restaurants, groceries, help in your language","description":"Checked in October 2026.\nVietnam: 4 restaurants — Wolnam Guksu, Pho Plus, Pho Ha Noi (downtown), Hanoi Pho (Hanam-eup).\nUzbekistan: there is an Uzbekistan Restaurant in Hanam-eup.\nThailand, Nepal, Mongolia, Cambodia: we found no restaurant from these countries.\nGroceries: of the shops called 'Asia Mart', we list the 2 whose addresses we could confirm — 1 in Naei-dong and 1 in Hanam-eup. Please check on site what they sell.\nPhone help in your language, 1577-0071: Vietnamese, Thai, Khmer, Nepali, Mongolian, Uzbek. 365 days a year, 09:00–18:00.\nPhone help in your language, 1345: 20 languages including Russian (Uzbek is not on the list). Weekdays 09:00–22:00; after 18:00 only Korean, English and Chinese."},"vi":{"name":"Hướng dẫn theo nước: quán ăn, thực phẩm, tư vấn bằng tiếng mẹ đẻ","description":"Nội dung này được kiểm tra vào tháng 10 năm 2026.\nViệt Nam: 4 quán ăn — Wolnam Guksu (월남국수), Phở Plus (쌀국수플러스), Phở Hà Nội (하노이쌀국수) ở trung tâm thành phố; Hanoi Pho (하노이퍼) ở thị trấn Hanam (하남읍).\nUzbekistan: ở thị trấn Hanam có Quán ăn Uzbekistan (우즈베키스탄식당).\nThái Lan, Nepal, Mông Cổ, Campuchia: chúng tôi không tìm thấy quán ăn của các nước này.\nThực phẩm: trong các cửa hàng tên là 'Asia Mart' (아시아마트), chúng tôi đăng 1 cửa hàng ở phường Naei (내이동) và 1 cửa hàng ở thị trấn Hanam, là những nơi đã xác nhận được địa chỉ. Cửa hàng bán gì thì bạn hãy đến xem.\nĐiện thoại tư vấn bằng tiếng mẹ đẻ 1577-0071: tiếng Việt, tiếng Thái, tiếng Campuchia, tiếng Nepal, tiếng Mông Cổ, tiếng Uzbek. 365 ngày, 09:00~18:00.\nĐiện thoại tư vấn bằng tiếng mẹ đẻ 1345: 20 ngôn ngữ, trong đó có tiếng Nga (tiếng Uzbek không có trong thông báo). Ngày thường 09:00~22:00, sau 18:00 chỉ có tiếng Hàn, tiếng Anh, tiếng Trung."},"km":{"name":"ព័ត៌មានតាមប្រទេស៖ ភោជនីយដ្ឋាន គ្រឿងធ្វើម្ហូប ប្រឹក្សាជាភាសារបស់អ្នក","description":"នេះជាព័ត៌មានដែលបានពិនិត្យនៅខែ 10 ឆ្នាំ 2026។\nវៀតណាម៖ ភោជនីយដ្ឋាន 4 កន្លែង — វ៉ុលណាមគុកស៊ូ (월남국수), សាល់គុកស៊ូផ្លឹស (쌀국수플러스), ហាណូយសាល់គុកស៊ូ (하노이쌀국수) នៅកណ្តាលក្រុង, ហាណូយភើ (하노이퍼) នៅទីប្រជុំជនហាណាម (하남읍)។\nអ៊ូសបេគីស្ថាន៖ នៅទីប្រជុំជនហាណាម មានភោជនីយដ្ឋានអ៊ូសបេគីស្ថាន (우즈베키스탄식당)។\nថៃ នេប៉ាល់ ម៉ុងហ្គោលី កម្ពុជា៖ យើងរកមិនឃើញភោជនីយដ្ឋានម្ហូបប្រទេសទាំងនេះទេ។\nគ្រឿងធ្វើម្ហូប៖ ក្នុងចំណោមហាងដែលមានឈ្មោះ «អាស៊ីម៉ាត» (아시아마트) យើងបានដាក់ហាងដែលបានបញ្ជាក់អាសយដ្ឋានរួច គឺនៅសង្កាត់ណែអ៊ី (내이동) 1 កន្លែង និងនៅទីប្រជុំជនហាណាម 1 កន្លែង។ សូមទៅមើលដោយផ្ទាល់ថាហាងលក់អ្វីខ្លះ។\nទូរស័ព្ទប្រឹក្សាជាភាសារបស់អ្នក 1577-0071៖ ភាសាវៀតណាម ថៃ ខ្មែរ នេប៉ាល់ ម៉ុងហ្គោលី អ៊ូសបេគីស្ថាន។ 365 ថ្ងៃ ម៉ោង 09:00~18:00។\nទូរស័ព្ទប្រឹក្សាជាភាសារបស់អ្នក 1345៖ 20 ភាសា រួមទាំងភាសារុស្ស៊ី (ភាសាអ៊ូសបេគីស្ថានមិនមានក្នុងសេចក្តីជូនដំណឹងទេ)។ ថ្ងៃធ្វើការ ម៉ោង 09:00~22:00។ ក្រោយម៉ោង 18:00 មានតែភាសាកូរ៉េ អង់គ្លេស និងចិនប៉ុណ្ណោះ។"},"th":{"name":"ข้อมูลแยกตามประเทศ: ร้านอาหาร·วัตถุดิบ·ปรึกษาเป็นภาษาของคุณ","description":"ข้อมูลนี้ตรวจสอบเมื่อเดือนตุลาคม 2026\nเวียดนาม: ร้านอาหาร 4 ร้าน — วอลนัมกุกซู (월남국수), ซัลกุกซูพลัส (쌀국수플러스), ฮานอยซัลกุกซู (하노이쌀국수) (ในตัวเมือง), ฮานอยพอ (하노이퍼) (ตำบลฮานัม (하남읍))\nอุซเบกิสถาน: ที่ตำบลฮานัมมีร้านอาหารอุซเบกิสถาน (우즈베키스탄식당)\nไทย เนปาล มองโกเลีย กัมพูชา: เราหาร้านอาหารของประเทศเหล่านี้ไม่พบ\nวัตถุดิบ: ในบรรดาร้านที่ชื่อ 'เอเชียมาร์ท' (아시아마트) เราลงไว้เฉพาะร้านที่ตรวจสอบที่อยู่ได้แล้ว คือที่ย่านแนอีดง (내이동) 1 ร้าน และที่ตำบลฮานัม 1 ร้าน ของที่ขายมีอะไรบ้าง ให้ไปดูที่ร้าน\nสายปรึกษาเป็นภาษาของคุณ 1577-0071: ภาษาเวียดนาม ภาษาไทย ภาษาเขมร ภาษาเนปาล ภาษามองโกเลีย ภาษาอุซเบก 365 วัน เวลา 09:00~18:00\nสายปรึกษาเป็นภาษาของคุณ 1345: 20 ภาษา เช่น ภาษารัสเซีย (ภาษาอุซเบกไม่มีในประกาศ) วันธรรมดา 09:00~22:00 หลัง 18:00 มีเฉพาะภาษาเกาหลี ภาษาอังกฤษ และภาษาจีน"},"ne":{"name":"देशअनुसार जानकारी: रेस्टुरेन्ट, खाद्य सामग्री, आफ्नै भाषामा परामर्श","description":"यो 2026 सालको अक्टोबरमा जाँचिएको जानकारी हो।\nभियतनाम: रेस्टुरेन्ट 4 वटा — वोल्नाम गुक्सु (월남국수), साल्गुक्सु प्लस (쌀국수플러스), हानोइ साल्गुक्सु (하노이쌀국수) [सहरको बीच भाग], हानोइ फो (하노이퍼) [हानाम-उप (하남읍)]।\nउज्बेकिस्तान: हानाम-उपमा उज्बेकिस्तान रेस्टुरेन्ट (우즈베키스탄식당) छ।\nथाइल्याण्ड, नेपाल, मङ्गोलिया, कम्बोडिया: यी देशका रेस्टुरेन्ट हामीले भेट्टाएनौँ।\nखाद्य सामग्री: 'एसिया मार्ट' (아시아마트) नामका पसलमध्ये ठेगाना पक्का भएका नेइ-दोङ (내이동) को 1 वटा र हानाम-उपको 1 वटा यहाँ राखिएको छ। के-के बेचिन्छ, त्यहाँ गएर हेर्नुहोस्।\nआफ्नै भाषामा परामर्श फोन 1577-0071: भियतनामी, थाई, खमेर, नेपाली, मङ्गोलियन, उज्बेक। वर्षको 365 दिनै 09:00~18:00।\nआफ्नै भाषामा परामर्श फोन 1345: रूसी लगायत 20 भाषा (उज्बेक भाषा जानकारीमा छैन)। सोमबार~शुक्रबार 09:00~22:00, 18:00 पछि कोरियन, अङ्ग्रेजी र चिनियाँ भाषा मात्र हुन्छ।"},"mn":{"name":"Улс орноор мэдээлэл: хоолны газар, хүнсний бараа, эх хэлээрээ зөвлөгөө","description":"2026 оны 10-р сард шалгасан мэдээлэл.\nВьетнам: хоолны газар 4 — хотын төвд Волнам Гүксү (월남국수), Ссалгүксү Плюс (쌀국수플러스), Ханой Ссалгүксү (하노이쌀국수); Ханам суурин (하남읍)-д Ханой Пө (하노이퍼).\nУзбекистан: Ханам сууринд Узбекистан хоолны газар (우즈베키스탄식당) байдаг.\nТайланд, Непал, Монгол, Камбож: эдгээр орны хоолны газар олдоогүй.\nХүнсний бараа: «Ази Март» (아시아마트) гэдэг нэртэй дэлгүүрүүдээс хаягийг нь шалгасан Нэи хороо (내이동)-ны 1, Ханам суурины 1 дэлгүүрийг оруулсан. Юу зардгийг очиж үзээрэй.\nЭх хэлээрээ зөвлөгөө авах утас 1577-0071: вьетнам, тайланд, камбож, непал, монгол, узбек хэл. Жилийн 365 өдөр, 09:00~18:00.\nЭх хэлээрээ зөвлөгөө авах утас 1345: орос зэрэг 20 хэл (узбек хэл мэдээлэлд байхгүй). Ажлын өдөр 09:00~22:00, 18:00 цагаас хойш зөвхөн солонгос, англи, хятад хэлээр."},"uz":{"name":"Mamlakatlar boʻyicha maʼlumot: taomxona, oziq-ovqat, ona tilida maslahat","description":"2026-yil oktyabr oyida tekshirilgan maʼlumot.\nVyetnam: 4 ta taomxona — Volnam Guksu (월남국수), Salguksu Plus (쌀국수플러스) va Hanoi Salguksu (하노이쌀국수) — shahar markazida; Hanoi Po (하노이퍼) — Hanam shaharchasida (하남읍).\nOʻzbekiston: Hanam shaharchasida Oʻzbekiston taomxonasi (우즈베키스탄식당) bor.\nTailand, Nepal, Moʻgʻuliston, Kambodja: bu mamlakatlar taomxonasini topa olmadik.\nOziq-ovqat mahsulotlari: «Asia Mart» (아시아마트) degan doʻkonlardan manzili tekshirilgan Naei mahallasidagi (내이동) 1 tasini va Hanam shaharchasidagi 1 tasini kiritdik. Nima sotilishini borib koʻring.\nOna tilida maslahat telefoni 1577-0071: vyetnam, tay, kambodja (kxmer), nepal, moʻgʻul, oʻzbek tillari. Yilning 365 kuni 09:00~18:00.\nOna tilida maslahat telefoni 1345: rus tili va boshqa tillar, jami 20 ta til (oʻzbek tili maʼlumotda koʻrsatilmagan). Ish kunlari 09:00~22:00, 18:00 dan keyin faqat koreys, ingliz va xitoy tillarida."},"ru":{"name":"По странам: кафе, продукты, помощь на вашем языке","description":"Эти сведения проверены в октябре 2026 года.\nВьетнам: 4 кафе — Вольнам Куксу (월남국수), Ссальгуксу Плюс (쌀국수플러스), Ханой Ссальгуксу (하노이쌀국수) [центр города], Ханой Пхо (하노이퍼) [посёлок Ханам (하남읍)].\nУзбекистан: в посёлке Ханам есть кафе «Узбекистан» (우즈베키스탄식당).\nТаиланд, Непал, Монголия, Камбоджа: кафе с кухней этих стран мы не нашли.\nПродукты: из магазинов с названием «Азия Март» (아시아마트) мы добавили те, у которых проверили адрес: 1 в районе Нэи-дон (내이동) и 1 в посёлке Ханам. Что там продают, посмотрите на месте.\nТелефон помощи на вашем языке 1577-0071: вьетнамский, тайский, кхмерский, непальский, монгольский, узбекский. 365 дней в году, 09:00~18:00.\nТелефон помощи на вашем языке 1345: 20 языков, в том числе русский (узбекского в объявлении нет). В будни 09:00~22:00, после 18:00 — только корейский, английский и китайский."}}$nsd$::jsonb,
 null,$nsd$1345$nsd$,null,null,null,'2026-10-13',true)
on conflict (id) do nothing;

-- 기존 행에 언어 추가: 예산군청 [예산군] — 새 언어 || 기존 값(겹치면 기존 값이 이긴다: ko·en 무변경)
update public.life_info set localized_content = $nsd${"vi":{"name":"Ủy ban huyện Yesan (예산군청)","description":"Đây là trụ sở huyện Yesan, nơi giải quyết các việc hành chính và giấy tờ của huyện. Từ ga Yesan hoặc bến xe tổng hợp Yesan, đi xe buýt nông thôn, xuống ở trạm 'Phố Chusa' (추사의 거리), rồi đi bộ khoảng 300m (5 phút)."},"km":{"name":"សាលាស្រុកយេសាន (예산군청)","description":"ជាអគារសាលាស្រុកយេសាន ដែលធ្វើការងាររដ្ឋបាល និងសេវាឯកសារទូទៅរបស់ស្រុក។ ពីស្ថានីយរថភ្លើងយេសាន (예산역) ឬចំណតឡានក្រុងយេសាន (예산종합터미널) សូមជិះឡានក្រុងជនបទ ចុះនៅចំណត «ផ្លូវឈូសា» ('추사의 거리') រួចដើរប្រហែល 300m (5 នាទី)។"},"th":{"name":"ที่ว่าการอำเภอเยซัน (예산군청)","description":"ที่ว่าการอำเภอเยซัน ดูแลงานราชการและงานบริการประชาชนทั่วไปของอำเภอ จากสถานีรถไฟเยซัน (예산역) หรือสถานีขนส่งเยซัน (예산종합터미널) ให้นั่งรถเมล์ชนบทไปลงที่ป้าย \"ถนนชูซา\" (추사의 거리) แล้วเดินประมาณ 300 ม. (5 นาที)"},"ne":{"name":"येसान काउन्टी कार्यालय (예산군청)","description":"यो येसान काउन्टीको कार्यालय हो, जहाँ काउन्टीका प्रशासन र सरकारी कागजपत्रका सबै काम हुन्छन्। येसान रेल स्टेसन वा येसान बस टर्मिनलबाट गाउँको बस चढेर 'छुसाको सडक (추사의 거리)' बस बिसौनीमा ओर्लनुहोस् र करिब 300m (5 मिनेट) हिँड्नुहोस्।"},"mn":{"name":"Есан сумын захиргаа (예산군청)","description":"Сумын захиргааны ажил, иргэдийн бичиг баримтын бүх ажлыг хийдэг Есан сумын захиргааны байр юм. Есан галт тэрэгний буудал эсвэл Есан автобусны нэгдсэн буудлаас хөдөөгийн автобусанд сууж, «Чүса-ий гори» (추사의 거리) буудал дээр буугаад 300 орчим метр (5 минут) явганаар явна."},"uz":{"name":"Yesan tumani hokimligi (예산군청)","description":"Yesan tumani hokimligi binosi. Bu yerda tumanning barcha maʼmuriy ishlari va fuqarolar murojaatlari koʻriladi. Yesan temir yoʻl stansiyasi yoki Yesan avtovokzalidan qishloq avtobusiga chiqib, «Chusa koʻchasi» (추사의 거리) bekatida tushing, keyin taxminan 300 m (5 daqiqa) piyoda yurasiz."},"ru":{"name":"Администрация уезда Йесан (예산군청)","description":"Это здание администрации уезда Йесан. Здесь решают все административные вопросы и принимают обращения жителей. От станции Йесан (예산역) или автовокзала Йесан (예산종합터미널) доезжайте на сельском автобусе до остановки «Улица Чхуса» (추사의 거리), потом идите пешком около 300 м (5 минут)."}}$nsd$::jsonb || localized_content
 where region_id = 'a1000000-0000-4000-8000-000000000014' and localized_content->'ko'->>'name' = $nsd$예산군청$nsd$;

-- 기존 행에 언어 추가: 홍성군청 [홍성군 홍성읍] — 새 언어 || 기존 값(겹치면 기존 값이 이긴다: ko·en 무변경)
update public.life_info set localized_content = $nsd${"vi":{"name":"Ủy ban huyện Hongseong (홍성군청)","description":"Nơi giải quyết các việc hành chính và giấy tờ của huyện. Ở đây cũng hướng dẫn bạn đến trung tâm hành chính phúc lợi của thị trấn, xã."},"km":{"name":"សាលាស្រុកហុងសុង (홍성군청)","description":"ធ្វើការងាររដ្ឋបាល និងសេវាឯកសារទូទៅរបស់ស្រុក។ អ្នកក៏អាចសួរព័ត៌មានអំពីមជ្ឈមណ្ឌលរដ្ឋបាលនិងសុខុមាលភាពរបស់ទីប្រជុំជន និងឃុំបានដែរ។"},"th":{"name":"ที่ว่าการอำเภอฮงซอง (홍성군청)","description":"ดูแลงานราชการและงานบริการประชาชนทั่วไปของอำเภอ และสอบถามเรื่องศูนย์บริการประชาชนของตำบล (읍·면 행정복지센터) ได้ด้วย"},"ne":{"name":"होङसङ काउन्टी कार्यालय (홍성군청)","description":"यहाँ काउन्टीका प्रशासन र सरकारी कागजपत्रका सबै काम हुन्छन्। टाउन र गाउँका प्रशासन-कल्याण केन्द्रबारे जानकारी पनि यहाँ पाइन्छ।"},"mn":{"name":"Хунсон сумын захиргаа (홍성군청)","description":"Сумын захиргааны ажил, иргэдийн бичиг баримтын бүх ажлыг хийдэг. Хот, тосгоны захиргаа-халамжийн төвийн талаар ч мэдээлэл авч болно."},"uz":{"name":"Hongseong tumani hokimligi (홍성군청)","description":"Tumanning barcha maʼmuriy ishlari va fuqarolar murojaatlari shu yerda koʻriladi. Shaharcha va qishloq maʼmuriy-ijtimoiy markazlari haqida ham maʼlumot olish mumkin."},"ru":{"name":"Администрация уезда Хонсон (홍성군청)","description":"Здесь решают все административные вопросы уезда и принимают обращения жителей. Здесь также подскажут, как найти центр административных и социальных услуг в вашем посёлке или волости."}}$nsd$::jsonb || localized_content
 where region_id = 'a2000000-0000-4000-8000-000000000001' and localized_content->'ko'->>'name' = $nsd$홍성군청$nsd$;

-- 기존 행에 언어 추가: 충청남도 홍성의료원 [홍성군 홍성읍] — 새 언어 || 기존 값(겹치면 기존 값이 이긴다: ko·en 무변경)
update public.life_info set localized_content = $nsd${"vi":{"name":"Bệnh viện Hongseong tỉnh Chungcheong Nam (충청남도 홍성의료원)","description":"Đây là bệnh viện đa khoa công của Hongseong. Có phòng cấp cứu."},"km":{"name":"មន្ទីរពេទ្យហុងសុង ខេត្តឈុងឆងណាំ (충청남도 홍성의료원)","description":"ជាមន្ទីរពេទ្យទូទៅសាធារណៈនៅហុងសុង។ មានបន្ទប់សង្គ្រោះបន្ទាន់។"},"th":{"name":"ศูนย์การแพทย์ฮงซอง (충청남도 홍성의료원)","description":"โรงพยาบาลทั่วไปของรัฐในฮงซอง มีห้องฉุกเฉิน"},"ne":{"name":"होङसङ मेडिकल सेन्टर (충청남도 홍성의료원)","description":"यो होङसङको सरकारी ठूलो अस्पताल हो। यहाँ आकस्मिक कक्ष छ।"},"mn":{"name":"Хунсон эмнэлгийн төв (충청남도 홍성의료원)","description":"Хунсоны улсын нэгдсэн эмнэлэг юм. Яаралтай тусламжийн тасагтай."},"uz":{"name":"Hongseong tibbiyot markazi (충청남도 홍성의료원)","description":"Hongseongdagi davlat umumiy shifoxonasi. Tez yordam boʻlimi bor."},"ru":{"name":"Медицинский центр Хонсон (충청남도 홍성의료원)","description":"Это государственная многопрофильная больница в Хонсоне. Есть отделение скорой помощи."}}$nsd$::jsonb || localized_content
 where region_id = 'a2000000-0000-4000-8000-000000000001' and localized_content->'ko'->>'name' = $nsd$충청남도 홍성의료원$nsd$;

-- 기존 행에 언어 추가: 예산군 보건소 [예산군] — 새 언어 || 기존 값(겹치면 기존 값이 이긴다: ko·en 무변경)
update public.life_info set localized_content = $nsd${"vi":{"name":"Trung tâm y tế công huyện Yesan (예산군 보건소)","description":"Đây là trung tâm y tế công do huyện Yesan điều hành, nằm cùng khu đất với ủy ban huyện ở số 22 đường Guncheong-ro (군청로 22). Từ ga Yesan hoặc bến xe tổng hợp Yesan, đi xe buýt, xuống ở trạm 'Phố Chusa' (추사의 거리), rồi đi bộ khoảng 500m."},"km":{"name":"មណ្ឌលសុខភាពសាធារណៈស្រុកយេសាន (예산군 보건소)","description":"ជាមណ្ឌលសុខភាពសាធារណៈដែលស្រុកយេសានគ្រប់គ្រង។ វានៅកន្លែងតែមួយជាមួយសាលាស្រុក គឺផ្លូវគុនឆង 22 (군청로 22)។ ពីស្ថានីយរថភ្លើងយេសាន (예산역) ឬចំណតឡានក្រុងយេសាន (예산종합터미널) សូមជិះឡានក្រុង ចុះនៅចំណត «ផ្លូវឈូសា» ('추사의 거리') រួចដើរប្រហែល 500m។"},"th":{"name":"ศูนย์สาธารณสุขอำเภอเยซัน (예산군 보건소)","description":"ศูนย์สาธารณสุขของรัฐที่อำเภอเยซันดูแล อยู่ในพื้นที่เดียวกับที่ว่าการอำเภอ ที่ถนนกุนชองโร 22 (군청로 22) จากสถานีรถไฟเยซัน (예산역) หรือสถานีขนส่งเยซัน (예산종합터미널) ให้นั่งรถเมล์ไปลงที่ป้าย \"ถนนชูซา\" (추사의 거리) แล้วเดินประมาณ 500 ม."},"ne":{"name":"येसान काउन्टी सरकारी स्वास्थ्य केन्द्र (예산군 보건소)","description":"यो येसान काउन्टीले चलाएको सरकारी स्वास्थ्य केन्द्र हो। यो काउन्टी कार्यालय भएकै ठाउँ, गुनछङ-रो 22 (군청로 22) मा छ। येसान रेल स्टेसन वा येसान बस टर्मिनलबाट बस चढेर 'छुसाको सडक (추사의 거리)' बस बिसौनीमा ओर्लनुहोस् र करिब 500m हिँड्नुहोस्।"},"mn":{"name":"Есан сумын эрүүл мэндийн төв (예산군 보건소)","description":"Есан сумын ажиллуулдаг улсын эрүүл мэндийн төв юм. Сумын захиргаатай нэг газарт, Гүнчон-ро 22 (군청로 22) хаягт байдаг. Есан галт тэрэгний буудал эсвэл Есан автобусны нэгдсэн буудлаас автобусанд сууж, «Чүса-ий гори» (추사의 거리) буудал дээр буугаад 500 орчим метр явганаар явна."},"uz":{"name":"Yesan tumani sogʻliqni saqlash markazi (예산군 보건소)","description":"Yesan tumani boshqaradigan davlat sogʻliqni saqlash markazi. Tuman hokimligi bilan bir joyda, Guncheong-ro 22 (군청로 22) manzilida joylashgan. Yesan temir yoʻl stansiyasi yoki Yesan avtovokzalidan avtobusga chiqib, «Chusa koʻchasi» (추사의 거리) bekatida tushing, keyin taxminan 500 m piyoda yurasiz."},"ru":{"name":"Центр здоровья уезда Йесан (예산군 보건소)","description":"Это государственный центр здоровья, им управляет уезд Йесан. Он находится на том же участке, что и администрация уезда: улица Кунчхон-ро, 22 (군청로 22). От станции Йесан (예산역) или автовокзала Йесан (예산종합터미널) доезжайте на автобусе до остановки «Улица Чхуса» (추사의 거리), потом идите пешком около 500 м."}}$nsd$::jsonb || localized_content
 where region_id = 'a1000000-0000-4000-8000-000000000014' and localized_content->'ko'->>'name' = $nsd$예산군 보건소$nsd$;

-- 기존 행에 언어 추가: 예산종합병원 (의료법인 예당의료재단) [예산군] — 새 언어 || 기존 값(겹치면 기존 값이 이긴다: ko·en 무변경)
update public.life_info set localized_content = $nsd${"vi":{"name":"Bệnh viện đa khoa Yesan (예산종합병원 (의료법인 예당의료재단))","description":"Đây là bệnh viện đa khoa duy nhất trong huyện (thuộc pháp nhân y tế tư nhân), có tên trong danh sách cơ sở y tế của trung tâm y tế công huyện Yesan. Theo trang web của bệnh viện, phòng cấp cứu mở cửa 24 giờ. Số điện thoại phòng cấp cứu là 041-330-4119."},"km":{"name":"មន្ទីរពេទ្យទូទៅយេសាន (예산종합병원 (의료법인 예당의료재단))","description":"ជាមន្ទីរពេទ្យទូទៅតែមួយគត់ក្នុងស្រុក (របស់មូលនិធិពេទ្យឯកជន) ដែលមានឈ្មោះក្នុងបញ្ជីកន្លែងព្យាបាលរបស់មណ្ឌលសុខភាពសាធារណៈស្រុកយេសាន។ តាមគេហទំព័ររបស់មន្ទីរពេទ្យ បន្ទប់សង្គ្រោះបន្ទាន់បើក 24 ម៉ោង។ លេខទូរស័ព្ទបន្ទប់សង្គ្រោះបន្ទាន់គឺ 041-330-4119។"},"th":{"name":"โรงพยาบาลทั่วไปเยซัน (예산종합병원 (의료법인 예당의료재단))","description":"โรงพยาบาลทั่วไปแห่งเดียวในอำเภอ (เป็นของมูลนิธิการแพทย์เอกชน) ที่ขึ้นทะเบียนในรายชื่อสถานพยาบาลของศูนย์สาธารณสุขอำเภอเยซัน ตามข้อมูลในเว็บไซต์ของโรงพยาบาล ห้องฉุกเฉินเปิด 24 ชั่วโมง เบอร์โทรห้องฉุกเฉินคือ 041-330-4119"},"ne":{"name":"येसान जनरल अस्पताल (예산종합병원 (의료법인 예당의료재단))","description":"येसान काउन्टी सरकारी स्वास्थ्य केन्द्रको स्वास्थ्य संस्था सूचीमा दर्ता भएको, यो काउन्टीभित्रको एक मात्र ठूलो अस्पताल (निजी मेडिकल संस्था) हो। अस्पतालको वेबसाइट अनुसार आकस्मिक कक्ष 24 घण्टा खुला रहन्छ। आकस्मिक कक्षको फोन 041-330-4119 हो।"},"mn":{"name":"Есан нэгдсэн эмнэлэг (예산종합병원 (의료법인 예당의료재단))","description":"Есан сумын эрүүл мэндийн төвийн эмнэлгийн байгууллагын жагсаалтад бүртгэлтэй, сум доторх цорын ганц нэгдсэн эмнэлэг (хувийн эмнэлгийн байгууллага) юм. Эмнэлгийн вэбсайтад бичсэнээр яаралтай тусламжийн тасаг 24 цаг ажилладаг. Яаралтай тусламжийн тасгийн утас: 041-330-4119."},"uz":{"name":"Yesan umumiy shifoxonasi (예산종합병원 (의료법인 예당의료재단))","description":"Yesan tumani sogʻliqni saqlash markazining tibbiyot muassasalari roʻyxatiga kiritilgan, tumandagi yagona umumiy shifoxona (xususiy tibbiyot tashkiloti). Shifoxona saytiga koʻra, tez yordam boʻlimi 24 soat ishlaydi. Tez yordam boʻlimi telefoni: 041-330-4119."},"ru":{"name":"Многопрофильная больница Йесан (예산종합병원 (의료법인 예당의료재단))","description":"Это единственная многопрофильная больница в уезде (частная медицинская организация). Она есть в списке медицинских учреждений центра здоровья уезда Йесан. По данным сайта больницы, отделение скорой помощи работает 24 часа. Телефон отделения скорой помощи: 041-330-4119."}}$nsd$::jsonb || localized_content
 where region_id = 'a1000000-0000-4000-8000-000000000014' and localized_content->'ko'->>'name' = $nsd$예산종합병원 (의료법인 예당의료재단)$nsd$;

-- 기존 행에 언어 추가: 홍성군보건소 [홍성군 홍성읍] — 새 언어 || 기존 값(겹치면 기존 값이 이긴다: ko·en 무변경)
update public.life_info set localized_content = $nsd${"vi":{"name":"Trung tâm y tế công huyện Hongseong (홍성군보건소)","description":"Đây là trung tâm y tế công, nơi bạn có thể tiêm phòng và khám bệnh cơ bản với giá rẻ."},"km":{"name":"មណ្ឌលសុខភាពសាធារណៈស្រុកហុងសុង (홍성군보건소)","description":"ជាមណ្ឌលសុខភាពសាធារណៈ ដែលអ្នកអាចចាក់វ៉ាក់សាំងការពារ និងពិនិត្យព្យាបាលជំងឺទូទៅបានក្នុងតម្លៃថោក។"},"th":{"name":"ศูนย์สาธารณสุขอำเภอฮงซอง (홍성군보건소)","description":"ศูนย์สาธารณสุขของรัฐ ฉีดวัคซีนและตรวจรักษาเบื้องต้นได้ในราคาถูก"},"ne":{"name":"होङसङ काउन्टी सरकारी स्वास्थ्य केन्द्र (홍성군보건소)","description":"यो सरकारी स्वास्थ्य केन्द्र हो, जहाँ खोप र सामान्य उपचार सस्तोमा पाइन्छ।"},"mn":{"name":"Хунсон сумын эрүүл мэндийн төв (홍성군보건소)","description":"Урьдчилан сэргийлэх тарилга, энгийн үзлэгийг хямд үнээр хийлгэж болох улсын эрүүл мэндийн төв юм."},"uz":{"name":"Hongseong tumani sogʻliqni saqlash markazi (홍성군보건소)","description":"Davlat sogʻliqni saqlash markazi. Bu yerda arzon narxda emlanish va oddiy tibbiy yordam olish mumkin."},"ru":{"name":"Центр здоровья уезда Хонсон (홍성군보건소)","description":"Это государственный центр здоровья. Здесь можно недорого сделать прививки и получить простую медицинскую помощь."}}$nsd$::jsonb || localized_content
 where region_id = 'a2000000-0000-4000-8000-000000000001' and localized_content->'ko'->>'name' = $nsd$홍성군보건소$nsd$;

-- 기존 행에 언어 추가: 홍성전통시장 [홍성군 홍성읍] — 새 언어 || 기존 값(겹치면 기존 값이 이긴다: ko·en 무변경)
update public.life_info set localized_content = $nsd${"vi":{"name":"Chợ truyền thống Hongseong (홍성전통시장)","description":"Đây là chợ truyền thống ở trung tâm thị trấn Hongseong."},"km":{"name":"ផ្សារប្រពៃណីហុងសុង (홍성전통시장)","description":"ជាផ្សារប្រពៃណីនៅកណ្ដាលទីប្រជុំជនហុងសុង (홍성읍)។"},"th":{"name":"ตลาดพื้นบ้านฮงซอง (홍성전통시장)","description":"ตลาดพื้นบ้านใจกลางตำบลฮงซอง (홍성읍)"},"ne":{"name":"होङसङ परम्परागत बजार (홍성전통시장)","description":"यो होङसङ टाउनको बीचमा रहेको परम्परागत बजार हो।"},"mn":{"name":"Хунсон уламжлалт зах (홍성전통시장)","description":"Хунсон хотын төвд байдаг уламжлалт зах юм."},"uz":{"name":"Hongseong anʼanaviy bozori (홍성전통시장)","description":"Hongseong shaharchasi (홍성읍) markazidagi anʼanaviy bozor."},"ru":{"name":"Традиционный рынок Хонсон (홍성전통시장)","description":"Это традиционный рынок в центре посёлка Хонсон."}}$nsd$::jsonb || localized_content
 where region_id = 'a2000000-0000-4000-8000-000000000001' and localized_content->'ko'->>'name' = $nsd$홍성전통시장$nsd$;

-- 기존 행에 언어 추가: 광천전통시장 [홍성군 광천읍] — 새 언어 || 기존 값(겹치면 기존 값이 이긴다: ko·en 무변경)
update public.life_info set localized_content = $nsd${"vi":{"name":"Chợ truyền thống Gwangcheon (광천전통시장)","description":"Đây là chợ truyền thống ở thị trấn Gwangcheon, nổi tiếng với mắm hải sản và rong biển khô (gim)."},"km":{"name":"ផ្សារប្រពៃណីក្វាងឆន (광천전통시장)","description":"ជាផ្សារប្រពៃណីនៅទីប្រជុំជនក្វាងឆន (광천읍) ដែលល្បីខាងគ្រឿងសមុទ្រផ្អាប់អំបិល និងសារាយសមុទ្រ (គីម)។"},"th":{"name":"ตลาดพื้นบ้านควังชอน (광천전통시장)","description":"ตลาดพื้นบ้านในตำบลควังชอน (광천읍) มีชื่อเสียงเรื่องอาหารทะเลหมักเค็ม (ชอทกัล) และสาหร่ายคิม"},"ne":{"name":"ग्वाङछन परम्परागत बजार (광천전통시장)","description":"यो ग्वाङछन टाउनको परम्परागत बजार हो। यो नुनमा गलाएको समुद्री खाना (젓갈) र समुद्री झार गिम (김) का लागि प्रसिद्ध छ।"},"mn":{"name":"Гуанчон уламжлалт зах (광천전통시장)","description":"Давсалсан далайн хүнс, далайн байцаа (гим)-аараа алдартай Гуанчон хотын уламжлалт зах юм."},"uz":{"name":"Gwangcheon anʼanaviy bozori (광천전통시장)","description":"Gwangcheon shaharchasidagi (광천읍) anʼanaviy bozor. Tuzlangan dengiz mahsulotlari va gim (dengiz oʻti) bilan mashhur."},"ru":{"name":"Традиционный рынок Кванчхон (광천전통시장)","description":"Это традиционный рынок в посёлке Кванчхон. Он известен солёными морепродуктами (чотгаль) и сушёными водорослями (ким)."}}$nsd$::jsonb || localized_content
 where region_id = 'a2000000-0000-4000-8000-000000000002' and localized_content->'ko'->>'name' = $nsd$광천전통시장$nsd$;

-- 기존 행에 언어 추가: 예산상설시장 [예산군] — 새 언어 || 기존 값(겹치면 기존 값이 이긴다: ko·en 무변경)
update public.life_info set localized_content = $nsd${"vi":{"name":"Chợ hằng ngày Yesan (예산상설시장)","description":"Đây là chợ truyền thống mở hằng ngày duy nhất của huyện Yesan, bán quần áo, rau, cá và các thứ khác. Cũng tại chỗ này, vào các ngày có số cuối là 5 và 10, có họp chợ phiên 5 ngày Yesan (예산5일장, còn gọi là chợ Yesan - 예산시장)."},"km":{"name":"ផ្សារប្រចាំថ្ងៃយេសាន (예산상설시장)","description":"ជាផ្សារប្រពៃណីតែមួយគត់ក្នុងស្រុកយេសានដែលបើករាល់ថ្ងៃ។ មានលក់សម្លៀកបំពាក់ បន្លែ ត្រី ជាដើម។ នៅកន្លែងដដែលនេះ ផ្សារ 5 ថ្ងៃម្ដងយេសាន (예산5일장 ឬ 예산시장) បើកនៅថ្ងៃទីដែលបញ្ចប់ដោយលេខ 5 និង 10។"},"th":{"name":"ตลาดประจำเยซัน (예산상설시장)","description":"ตลาดพื้นบ้านที่เปิดเป็นประจำแห่งเดียวของอำเภอเยซัน ขายเสื้อผ้า ผัก ปลา เป็นต้น และที่เดียวกันนี้มีตลาดนัดทุก 5 วันของเยซัน (예산5일장 หรือ 예산시장) ในวันที่ลงท้ายด้วยเลข 5 และ 0 (วันตลาดนัด 5·10)"},"ne":{"name":"येसान दैनिक बजार (예산상설시장)","description":"यो येसान काउन्टीको एक मात्र सधैँ खुल्ने परम्परागत बजार हो। यहाँ लुगा, तरकारी, माछा आदि पाइन्छ। यही ठाउँमा तारिखको अन्तिम अङ्क 5 र 10 भएका दिन हरेक 5 दिनमा लाग्ने येसान हाट (예산5일장, येसान बजार) लाग्छ।"},"mn":{"name":"Есан байнгын зах (예산상설시장)","description":"Есан сумын цорын ганц байнгын уламжлалт зах юм. Хувцас, хүнсний ногоо, загас зэргийг зардаг. Мөн энэ газарт сарын 5, 10-аар төгссөн өдрүүдэд Есан 5 хоног тутмын зах (예산5일장, Есан зах) болдог."},"uz":{"name":"Yesan doimiy bozori (예산상설시장)","description":"Yesan tumanidagi yagona doimiy anʼanaviy bozor. Kiyim, sabzavot, baliq va boshqa narsalar sotiladi. Shu joyning oʻzida sanasi 5 va 10 bilan tugaydigan kunlari Yesan besh kunlik bozori (예산5일장, 예산시장) boʻladi."},"ru":{"name":"Постоянный рынок Йесан (예산상설시장)","description":"Это единственный постоянный традиционный рынок в уезде Йесан. Здесь продают одежду, овощи, рыбу и другое. На этом же месте по числам, которые заканчиваются на 5 и 10, работает пятидневный рынок Йесан (예산5일장, 예산시장)."}}$nsd$::jsonb || localized_content
 where region_id = 'a1000000-0000-4000-8000-000000000014' and localized_content->'ko'->>'name' = $nsd$예산상설시장$nsd$;

-- 기존 행에 언어 추가: 홍성군가족센터 [홍성군 홍북읍] — 새 언어 || 기존 값(겹치면 기존 값이 이긴다: ko·en 무변경)
update public.life_info set localized_content = $nsd${"vi":{"name":"Trung tâm gia đình huyện Hongseong (홍성군가족센터)","description":"Nơi đây có các chương trình dành cho gia đình đa văn hóa và người nước ngoài sống ở địa phương, và tư vấn về việc học tiếng Hàn."},"km":{"name":"មជ្ឈមណ្ឌលគ្រួសារស្រុកហុងសុង (홍성군가족센터)","description":"ផ្ដល់កម្មវិធីសម្រាប់គ្រួសារពហុវប្បធម៌ និងជនបរទេសដែលរស់នៅទីនេះ ព្រមទាំងការប្រឹក្សាអំពីការរៀនភាសាកូរ៉េ។"},"th":{"name":"ศูนย์ครอบครัวอำเภอฮงซอง (홍성군가족센터)","description":"มีกิจกรรมสำหรับครอบครัวพหุวัฒนธรรมและชาวต่างชาติในพื้นที่ และให้คำปรึกษาเรื่องการเรียนภาษาเกาหลี"},"ne":{"name":"होङसङ काउन्टी परिवार केन्द्र (홍성군가족센터)","description":"यहाँ बहुसांस्कृतिक परिवार र विदेशी बासिन्दाका लागि कार्यक्रम तथा कोरियन भाषा पढाइबारे परामर्श दिइन्छ।"},"mn":{"name":"Хунсон сумын гэр бүлийн төв (홍성군가족센터)","description":"Олон соёлт гэр бүл, гадаад оршин суугчдад зориулсан хөтөлбөр явуулж, солонгос хэлний сургалтын зөвлөгөө өгдөг."},"uz":{"name":"Hongseong tumani oila markazi (홍성군가족센터)","description":"Koʻp madaniyatli oilalar va chet ellik aholi uchun dasturlar oʻtkazadi hamda koreys tili taʼlimi boʻyicha maslahat beradi."},"ru":{"name":"Семейный центр уезда Хонсон (홍성군가족센터)","description":"Здесь есть программы для многокультурных семей и жителей-иностранцев. Здесь также консультируют по обучению корейскому языку."}}$nsd$::jsonb || localized_content
 where region_id = 'a2000000-0000-4000-8000-000000000003' and localized_content->'ko'->>'name' = $nsd$홍성군가족센터$nsd$;

-- 기존 행에 언어 추가: 예산군 가족센터 [예산군] — 새 언어 || 기존 값(겹치면 기존 값이 이긴다: ko·en 무변경)
update public.life_info set localized_content = $nsd${"vi":{"name":"Trung tâm gia đình huyện Yesan (예산군 가족센터)","description":"Đây là trung tâm gia đình do Phòng Hỗ trợ gia đình của huyện Yesan trực tiếp điều hành. Trung tâm dạy tiếng Hàn cho gia đình đa văn hóa và hỗ trợ con em học kiến thức cơ bản. Số điện thoại dịch vụ thông dịch và biên dịch là 041-339-8386."},"km":{"name":"មជ្ឈមណ្ឌលគ្រួសារស្រុកយេសាន (예산군 가족센터)","description":"ជាមជ្ឈមណ្ឌលគ្រួសារដែលផ្នែកជំនួយគ្រួសាររបស់ស្រុកយេសានគ្រប់គ្រងដោយផ្ទាល់។ មានបង្រៀនភាសាកូរ៉េដល់គ្រួសារពហុវប្បធម៌ និងជួយការរៀនមូលដ្ឋានរបស់កូនៗ។ លេខទូរស័ព្ទសេវាបកប្រែគឺ 041-339-8386។"},"th":{"name":"ศูนย์ครอบครัวอำเภอเยซัน (예산군 가족센터)","description":"ศูนย์ครอบครัวที่กองสนับสนุนครอบครัวของอำเภอเยซันดูแลเอง สอนภาษาเกาหลีให้ครอบครัวพหุวัฒนธรรม และช่วยเรื่องการเรียนพื้นฐานของลูก เบอร์โทรงานล่ามและแปลคือ 041-339-8386"},"ne":{"name":"येसान काउन्टी परिवार केन्द्र (예산군 가족센터)","description":"यो येसान काउन्टीको परिवार सहयोग विभागले आफैँ चलाएको परिवार केन्द्र हो। यहाँ बहुसांस्कृतिक परिवारलाई कोरियन भाषा सिकाइन्छ र बालबालिकाको आधारभूत पढाइमा सहयोग गरिन्छ। दोभाषे र अनुवाद सेवाको फोन 041-339-8386 हो।"},"mn":{"name":"Есан сумын гэр бүлийн төв (예산군 가족센터)","description":"Есан сумын Гэр бүлийг дэмжих хэлтэс шууд ажиллуулдаг гэр бүлийн төв юм. Олон соёлт гэр бүлд солонгос хэл заадаг, хүүхдийн суурь хичээлд тусалдаг. Орчуулга, хэлмэрчийн үйлчилгээний утас: 041-339-8386."},"uz":{"name":"Yesan tumani oila markazi (예산군 가족센터)","description":"Yesan tumani hokimligining Oilani qoʻllab-quvvatlash boʻlimi oʻzi boshqaradigan oila markazi. Koʻp madaniyatli oilalarga koreys tilini oʻrgatadi va bolalarning boshlangʻich oʻqishiga yordam beradi. Ogʻzaki va yozma tarjima xizmati telefoni: 041-339-8386."},"ru":{"name":"Семейный центр уезда Йесан (예산군 가족센터)","description":"Этим семейным центром напрямую управляет отдел поддержки семьи уезда Йесан. Здесь учат корейскому языку многокультурные семьи и помогают их детям с основами учёбы. Телефон службы устного и письменного перевода: 041-339-8386."}}$nsd$::jsonb || localized_content
 where region_id = 'a1000000-0000-4000-8000-000000000014' and localized_content->'ko'->>'name' = $nsd$예산군 가족센터$nsd$;

-- 기존 행에 언어 추가: 외국인종합안내센터 ☎1345 [홍성군] — 새 언어 || 기존 값(겹치면 기존 값이 이긴다: ko·en 무변경)
update public.life_info set localized_content = $nsd${"vi":{"name":"Trung tâm hướng dẫn tổng hợp cho người nước ngoài ☎1345 (외국인종합안내센터)","description":"Đây là tổng đài của chính phủ, hướng dẫn bằng nhiều thứ tiếng về cư trú, visa và mọi việc trong đời sống. Gọi 1345, không cần bấm mã vùng."},"km":{"name":"មជ្ឈមណ្ឌលព័ត៌មានសម្រាប់ជនបរទេស ☎1345 (외국인종합안내센터)","description":"ជាមជ្ឈមណ្ឌលទូរស័ព្ទរបស់រដ្ឋាភិបាល ដែលផ្ដល់ព័ត៌មានជាច្រើនភាសាអំពីការស្នាក់នៅ វីសា និងការរស់នៅទូទៅ។ ចុច 1345 ដោយមិនបាច់ថែមលេខតំបន់។"},"th":{"name":"ศูนย์ข้อมูลสำหรับชาวต่างชาติ ☎1345 (외국인종합안내센터)","description":"คอลเซ็นเตอร์ของรัฐบาล ให้ข้อมูลเรื่องการพำนัก วีซ่า และชีวิตประจำวันทั่วไปได้หลายภาษา กด 1345 ได้เลย ไม่ต้องกดรหัสพื้นที่"},"ne":{"name":"विदेशीका लागि जानकारी केन्द्र ☎1345 (외국인종합안내센터)","description":"यो सरकारी कल सेन्टर हो, जसले बसाइ, भिसा र दैनिक जीवनका सबै कुरा धेरै भाषामा बताउँछ। एरिया कोड नथिची 1345 मा फोन गर्नुहोस्।"},"mn":{"name":"Гадаад иргэдийн мэдээллийн төв ☎1345 (외국인종합안내센터)","description":"Оршин суух, виз, өдөр тутмын амьдралын бүх асуудлаар олон хэлээр мэдээлэл өгдөг засгийн газрын дуудлагын төв юм. Бүсийн код хэрэггүй, 1345 руу залгана."},"uz":{"name":"Chet elliklar uchun maʼlumot markazi ☎1345 (외국인종합안내센터)","description":"Yashash muddati, viza va kundalik hayot boʻyicha bir necha tilda maʼlumot beradigan davlat qoʻngʻiroq markazi. Hudud kodisiz 1345 ga qoʻngʻiroq qiling."},"ru":{"name":"Справочный центр для иностранцев ☎1345 (외국인종합안내센터)","description":"Это государственный колл-центр. Здесь на разных языках отвечают на вопросы о пребывании в стране, визах и повседневной жизни. Звоните 1345 без кода города."}}$nsd$::jsonb || localized_content
 where region_id = 'a1000000-0000-4000-8000-000000000001' and localized_content->'ko'->>'name' = $nsd$외국인종합안내센터 ☎1345$nsd$;

-- 기존 행에 언어 추가: 고용노동부 상담센터 ☎1350 [홍성군] — 새 언어 || 기존 값(겹치면 기존 값이 이긴다: ko·en 무변경)
update public.life_info set localized_content = $nsd${"vi":{"name":"Trung tâm tư vấn Bộ Việc làm và Lao động ☎1350 (고용노동부 상담센터)","description":"Tư vấn các vấn đề về công việc như bị nợ lương, hợp đồng lao động, tai nạn lao động. Gọi 1350, không cần bấm mã vùng."},"km":{"name":"មជ្ឈមណ្ឌលប្រឹក្សាក្រសួងការងារ ☎1350 (고용노동부 상담센터)","description":"ប្រឹក្សាអំពីបញ្ហាការងារ ដូចជា មិនបានប្រាក់ឈ្នួល កិច្ចសន្យាការងារ គ្រោះថ្នាក់ការងារ ជាដើម។ ចុច 1350 ដោយមិនបាច់ថែមលេខតំបន់។"},"th":{"name":"ศูนย์ปรึกษากระทรวงแรงงาน ☎1350 (고용노동부 상담센터)","description":"ปรึกษาปัญหาเรื่องงาน เช่น ค้างจ่ายค่าจ้าง สัญญาจ้าง อุบัติเหตุจากการทำงาน กด 1350 ได้เลย ไม่ต้องกดรหัสพื้นที่"},"ne":{"name":"रोजगार तथा श्रम मन्त्रालय परामर्श केन्द्र ☎1350 (고용노동부 상담센터)","description":"तलब नपाएको, काम सम्झौता, काममा लागेको चोटपटक जस्ता कामका समस्याबारे परामर्श। एरिया कोड नथिची 1350 मा फोन गर्नुहोस्।"},"mn":{"name":"Хөдөлмөрийн яамны зөвлөгөөний төв ☎1350 (고용노동부 상담센터)","description":"Цалингаа авч чадаагүй, хөдөлмөрийн гэрээ, ажлын үеийн осол гэмтэл зэрэг ажлын асуудлаар зөвлөгөө өгнө. Бүсийн код хэрэггүй, 1350 руу залгана."},"uz":{"name":"Bandlik va mehnat vazirligi maslahat markazi ☎1350 (고용노동부 상담센터)","description":"Ish haqi toʻlanmasligi, mehnat shartnomasi, ishdagi baxtsiz hodisa kabi ish muammolari boʻyicha maslahat. Hudud kodisiz 1350 ga qoʻngʻiroq qiling."},"ru":{"name":"Консультационный центр Министерства труда ☎1350 (고용노동부 상담센터)","description":"Консультации по рабочим вопросам: невыплата зарплаты, трудовой договор, травмы на работе и другое. Звоните 1350 без кода города."}}$nsd$::jsonb || localized_content
 where region_id = 'a1000000-0000-4000-8000-000000000001' and localized_content->'ko'->>'name' = $nsd$고용노동부 상담센터 ☎1350$nsd$;

-- 기존 행에 언어 추가: 긴급 신고 ☎112 [홍성군] — 새 언어 || 기존 값(겹치면 기존 값이 이긴다: ko·en 무변경)
update public.life_info set localized_content = $nsd${"vi":{"name":"Báo khẩn cấp ☎112 (긴급 신고)","description":"Khi gặp tình huống nguy cấp như bị bạo lực, bị giam giữ, hãy gọi báo ngay cho 112."},"km":{"name":"រាយការណ៍បន្ទាន់ ☎112 (긴급 신고)","description":"ពេលមានគ្រោះថ្នាក់បន្ទាន់ ដូចជា អំពើហិង្សា ឬត្រូវគេបង្ខាំងទុក សូមទូរស័ព្ទរាយការណ៍ទៅលេខ 112 ភ្លាម។"},"th":{"name":"แจ้งเหตุด่วน ☎112 (긴급 신고)","description":"ถ้าอยู่ในสถานการณ์อันตราย เช่น ถูกทำร้ายหรือถูกกักขัง ให้โทรแจ้ง 112 ทันที"},"ne":{"name":"आपत्कालीन खबर ☎112 (긴급 신고)","description":"हिंसा, थुनेर राख्ने जस्तो खतराको अवस्थामा तुरुन्तै 112 मा फोन गरेर खबर गर्नुहोस्।"},"mn":{"name":"Яаралтай дуудлага ☎112 (긴급 신고)","description":"Хүчирхийлэлд өртөх, хоригдох зэрэг аюултай үед шууд 112 руу залгаж мэдэгдээрэй."},"uz":{"name":"Shoshilinch xabar berish ☎112 (긴급 신고)","description":"Zoʻravonlik, qamab qoʻyish kabi xavfli vaziyatda darhol 112 ga qoʻngʻiroq qiling."},"ru":{"name":"Экстренный вызов ☎112 (긴급 신고)","description":"В опасной ситуации, например если вас бьют или держат взаперти, сразу звоните 112."}}$nsd$::jsonb || localized_content
 where region_id = 'a1000000-0000-4000-8000-000000000001' and localized_content->'ko'->>'name' = $nsd$긴급 신고 ☎112$nsd$;

-- 기존 행에 언어 추가: 다누리콜센터 ☎1577-1366 [홍성군] — 새 언어 || 기존 값(겹치면 기존 값이 이긴다: ko·en 무변경)
update public.life_info set localized_content = $nsd${"vi":{"name":"Tổng đài Danuri ☎1577-1366 (다누리콜센터)","description":"Tư vấn 24 giờ bằng nhiều thứ tiếng cho người bị bạo lực và người có vấn đề gia đình."},"km":{"name":"មជ្ឈមណ្ឌលទូរស័ព្ទដានូរី ☎1577-1366 (다누리콜센터)","description":"ផ្ដល់ការប្រឹក្សាជាច្រើនភាសា 24 ម៉ោង អំពីការរងអំពើហិង្សា និងបញ្ហាគ្រួសារ។"},"th":{"name":"คอลเซ็นเตอร์ดานูรี ☎1577-1366 (다누리콜센터)","description":"ให้คำปรึกษาเรื่องการถูกทำร้ายและปัญหาครอบครัวได้หลายภาษา ตลอด 24 ชั่วโมง"},"ne":{"name":"दानुरी कल सेन्टर ☎1577-1366 (다누리콜센터)","description":"हिंसामा परेको र परिवारको समस्याबारे धेरै भाषामा 24 घण्टा परामर्श दिइन्छ।"},"mn":{"name":"Данүри дуудлагын төв ☎1577-1366 (다누리콜센터)","description":"Хүчирхийлэлд өртсөн үед болон гэр бүлийн асуудлаар олон хэлээр 24 цаг зөвлөгөө өгдөг."},"uz":{"name":"Danuri qoʻngʻiroq markazi ☎1577-1366 (다누리콜센터)","description":"Zoʻravonlikdan jabr koʻrganlarga va oilaviy muammolar boʻyicha bir necha tilda 24 soat maslahat beradi."},"ru":{"name":"Колл-центр Данури ☎1577-1366 (다누리콜센터)","description":"Здесь 24 часа в сутки на разных языках консультируют тех, кто пострадал от насилия, и помогают с семейными проблемами."}}$nsd$::jsonb || localized_content
 where region_id = 'a1000000-0000-4000-8000-000000000001' and localized_content->'ko'->>'name' = $nsd$다누리콜센터 ☎1577-1366$nsd$;

-- 기존 행에 언어 추가: 홍성종합터미널 [홍성군 홍성읍] — 새 언어 || 기존 값(겹치면 기존 값이 이긴다: ko·en 무변경)
update public.life_info set localized_content = $nsd${"vi":{"name":"Bến xe tổng hợp Hongseong (홍성종합터미널)","description":"Đây là bến xe buýt liên tỉnh và xe buýt cao tốc."},"km":{"name":"ចំណតឡានក្រុងហុងសុង (홍성종합터미널)","description":"ជាចំណតឡានក្រុងឆ្លងក្រុង និងឡានក្រុងរហ័ស។"},"th":{"name":"สถานีขนส่งฮงซอง (홍성종합터미널)","description":"สถานีรถบัสระหว่างเมืองและรถบัสด่วน"},"ne":{"name":"होङसङ बस टर्मिनल (홍성종합터미널)","description":"यो अन्तरसहर र एक्सप्रेस बसको टर्मिनल हो।"},"mn":{"name":"Хунсон автобусны нэгдсэн буудал (홍성종합터미널)","description":"Хот хоорондын болон буухиа автобусны буудал юм."},"uz":{"name":"Hongseong avtovokzali (홍성종합터미널)","description":"Shaharlararo va tezyurar avtobuslar avtovokzali."},"ru":{"name":"Автовокзал Хонсон (홍성종합터미널)","description":"Это автовокзал для междугородних и скоростных автобусов."}}$nsd$::jsonb || localized_content
 where region_id = 'a2000000-0000-4000-8000-000000000001' and localized_content->'ko'->>'name' = $nsd$홍성종합터미널$nsd$;

-- 기존 행에 언어 추가: 예산역 [예산군] — 새 언어 || 기존 값(겹치면 기존 값이 이긴다: ko·en 무변경)
update public.life_info set localized_content = $nsd${"vi":{"name":"Ga Yesan (예산역)","description":"Đây là ga của Korail, nơi các tàu thường của tuyến Janghang (장항선) dừng lại. Theo hướng dẫn của ủy ban huyện Yesan, từ ga Yongsan (용산역) đi tàu Mugunghwa (무궁화호) mất khoảng 2 giờ (1 ngày 15 chuyến)."},"km":{"name":"ស្ថានីយរថភ្លើងយេសាន (예산역)","description":"ជាស្ថានីយរបស់ក្រុមហ៊ុនរថភ្លើងកូរ៉េ (Korail) ដែលរថភ្លើងធម្មតានៃខ្សែចាងហាង (장항선) ឈប់។ តាមព័ត៌មានរបស់សាលាស្រុកយេសាន ពីស្ថានីយរថភ្លើងយ៉ុងសាន (용산역) ជិះរថភ្លើងមូគុងហ្វា (무궁화호) ប្រហែល 2 ម៉ោង (1 ថ្ងៃ 15 ដង)។"},"th":{"name":"สถานีรถไฟเยซัน (예산역)","description":"สถานีรถไฟของโคเรล (Korail) ที่รถไฟธรรมดาสายชังฮัง (장항선) จอด ตามข้อมูลของที่ว่าการอำเภอเยซัน จากสถานียงซาน (용산역) นั่งรถไฟมูกุงฮวา (무궁화호) ประมาณ 2 ชั่วโมง (วันละ 15 เที่ยว)"},"ne":{"name":"येसान रेल स्टेसन (예산역)","description":"यो कोरेलको रेल स्टेसन हो, जहाँ जाङहाङ लाइन (장항선) का साधारण रेल रोकिन्छन्। येसान काउन्टी कार्यालयको जानकारी अनुसार योङसान स्टेसन (용산역) बाट मुगुङह्वा (무궁화호) रेलमा करिब 2 घण्टा लाग्छ (दिनमा 15 पटक)।"},"mn":{"name":"Есан галт тэрэгний буудал (예산역)","description":"Жанхан шугамын (장항선) энгийн галт тэрэг зогсдог Корейл (Korail)-ийн буудал юм. Есан сумын захиргааны мэдээллээр Ёнсан буудлаас (용산역) Мүгүнхуа (무궁화호) галт тэргээр 2 орчим цаг явна (өдөрт 15 удаа)."},"uz":{"name":"Yesan temir yoʻl stansiyasi (예산역)","description":"Janghang yoʻnalishidagi (장항선) oddiy poyezdlar toʻxtaydigan Korail stansiyasi. Yesan tumani hokimligi maʼlumotiga koʻra, Yongsan stansiyasidan (용산역) Mugunghwa (무궁화호) poyezdida taxminan 2 soat (kuniga 15 marta)."},"ru":{"name":"Станция Йесан (예산역)","description":"Это станция компании Korail на линии Чанхан (장항선). Здесь останавливаются обычные поезда. По данным администрации уезда Йесан, от станции Йонсан (용산역) на поезде «Мугунхва» (무궁화호) ехать около 2 часов (15 рейсов в день)."}}$nsd$::jsonb || localized_content
 where region_id = 'a1000000-0000-4000-8000-000000000014' and localized_content->'ko'->>'name' = $nsd$예산역$nsd$;

-- 기존 행에 언어 추가: 광천역 [홍성군 광천읍] — 새 언어 || 기존 값(겹치면 기존 값이 이긴다: ko·en 무변경)
update public.life_info set localized_content = $nsd${"vi":{"name":"Ga Gwangcheon (광천역)","description":"Đây là ga tàu hỏa của tuyến Janghang (장항선). Số điện thoại là của trung tâm chăm sóc khách hàng Korail."},"km":{"name":"ស្ថានីយរថភ្លើងក្វាងឆន (광천역)","description":"ជាស្ថានីយរថភ្លើងនៃខ្សែចាងហាង (장항선)។ លេខទូរស័ព្ទគឺជាលេខមជ្ឈមណ្ឌលបម្រើអតិថិជន Korail។"},"th":{"name":"สถานีรถไฟควังชอน (광천역)","description":"สถานีรถไฟสายชังฮัง (장항선) เบอร์โทรเป็นเบอร์ศูนย์บริการลูกค้าโคเรล (Korail)"},"ne":{"name":"ग्वाङछन रेल स्टेसन (광천역)","description":"यो जाङहाङ लाइन (장항선) को रेल स्टेसन हो। फोन नम्बर कोरेल ग्राहक केन्द्रको हो।"},"mn":{"name":"Гуанчон галт тэрэгний буудал (광천역)","description":"Жанхан шугамын (장항선) галт тэрэгний буудал юм. Утасны дугаар нь Корейл (Korail)-ийн үйлчлүүлэгчийн төвийнх."},"uz":{"name":"Gwangcheon temir yoʻl stansiyasi (광천역)","description":"Janghang yoʻnalishidagi (장항선) temir yoʻl stansiyasi. Telefon raqami — Korail mijozlar markazi raqami."},"ru":{"name":"Станция Кванчхон (광천역)","description":"Это железнодорожная станция на линии Чанхан (장항선). Указанный телефон — это телефон центра обслуживания клиентов Korail."}}$nsd$::jsonb || localized_content
 where region_id = 'a2000000-0000-4000-8000-000000000002' and localized_content->'ko'->>'name' = $nsd$광천역$nsd$;

-- 기존 행에 언어 추가: 예산종합터미널 [예산군] — 새 언어 || 기존 값(겹치면 기존 값이 이긴다: ko·en 무변경)
update public.life_info set localized_content = $nsd${"vi":{"name":"Bến xe tổng hợp Yesan (예산종합터미널)","description":"Đây là bến xe buýt tổng hợp của huyện Yesan, có cả xe buýt cao tốc, xe buýt liên tỉnh và xe buýt trong huyện (xe buýt nông thôn). Theo hướng dẫn của ủy ban huyện Yesan, từ bến xe Nambu Seoul (서울남부터미널) đi mất khoảng 2 giờ."},"km":{"name":"ចំណតឡានក្រុងយេសាន (예산종합터미널)","description":"ជាចំណតឡានក្រុងធំរបស់ស្រុកយេសាន ដែលមានឡានក្រុងរហ័ស ឡានក្រុងឆ្លងក្រុង និងឡានក្រុងក្នុងស្រុក (ឡានក្រុងជនបទ) រត់ជាមួយគ្នា។ តាមព័ត៌មានរបស់សាលាស្រុកយេសាន ពីចំណតឡានក្រុងសេអ៊ូលណាំប៊ូ (서울남부터미널) មកប្រហែល 2 ម៉ោង។"},"th":{"name":"สถานีขนส่งเยซัน (예산종합터미널)","description":"สถานีขนส่งรวมของอำเภอเยซัน มีทั้งรถบัสด่วน รถบัสระหว่างเมือง และรถเมล์ในอำเภอ (รถเมล์ชนบท) ตามข้อมูลของที่ว่าการอำเภอเยซัน จากสถานีขนส่งโซลนัมบู (서울남부터미널) ใช้เวลาประมาณ 2 ชั่วโมง"},"ne":{"name":"येसान बस टर्मिनल (예산종합터미널)","description":"यो येसान काउन्टीको मुख्य बस टर्मिनल हो, जहाँ एक्सप्रेस बस, अन्तरसहर बस र काउन्टीभित्र चल्ने (गाउँको) बस सबै चल्छन्। येसान काउन्टी कार्यालयको जानकारी अनुसार सियोल नाम्बु टर्मिनल (서울남부터미널) बाट करिब 2 घण्टा लाग्छ।"},"mn":{"name":"Есан автобусны нэгдсэн буудал (예산종합터미널)","description":"Буухиа, хот хоорондын автобус болон сум доторх (хөдөөгийн) автобус хамт явдаг Есан сумын автобусны нэгдсэн буудал юм. Есан сумын захиргааны мэдээллээр Сөүлийн Намбү автобусны буудлаас (서울남부터미널) 2 орчим цаг явна."},"uz":{"name":"Yesan avtovokzali (예산종합터미널)","description":"Yesan tumanining umumiy avtovokzali. Bu yerdan tezyurar, shaharlararo va tuman ichidagi (qishloq) avtobuslar qatnaydi. Yesan tumani hokimligi maʼlumotiga koʻra, Seul Nambu avtovokzalidan (서울남부터미널) taxminan 2 soat."},"ru":{"name":"Автовокзал Йесан (예산종합터미널)","description":"Это главный автовокзал уезда Йесан. Отсюда ходят скоростные и междугородние автобусы, а также местные (сельские) автобусы по уезду. По данным администрации уезда Йесан, от Южного автовокзала Сеула (서울남부터미널) ехать около 2 часов."}}$nsd$::jsonb || localized_content
 where region_id = 'a1000000-0000-4000-8000-000000000014' and localized_content->'ko'->>'name' = $nsd$예산종합터미널$nsd$;

-- 기존 행에 언어 추가: 홍성역 [홍성군 홍성읍] — 새 언어 || 기존 값(겹치면 기존 값이 이긴다: ko·en 무변경)
update public.life_info set localized_content = $nsd${"vi":{"name":"Ga Hongseong (홍성역)","description":"Đây là ga tàu hỏa của tuyến Janghang (장항선), hướng đi Yongsan và Cheonan."},"km":{"name":"ស្ថានីយរថភ្លើងហុងសុង (홍성역)","description":"ជាស្ថានីយរថភ្លើងនៃខ្សែចាងហាង (장항선) (ទៅទិសយ៉ុងសាន និងឆនអាន)។"},"th":{"name":"สถานีรถไฟฮงซอง (홍성역)","description":"สถานีรถไฟสายชังฮัง (장항선) (ไปทางยงซานและชอนัน)"},"ne":{"name":"होङसङ रेल स्टेसन (홍성역)","description":"यो जाङहाङ लाइन (장항선) को रेल स्टेसन हो (योङसान र छनान तर्फ)।"},"mn":{"name":"Хунсон галт тэрэгний буудал (홍성역)","description":"Жанхан шугамын (장항선) галт тэрэгний буудал юм (Ёнсан, Чонан чиглэл)."},"uz":{"name":"Hongseong temir yoʻl stansiyasi (홍성역)","description":"Janghang yoʻnalishidagi (장항선) temir yoʻl stansiyasi (Yongsan va Cheonan tomonga)."},"ru":{"name":"Станция Хонсон (홍성역)","description":"Это железнодорожная станция на линии Чанхан (장항선), в сторону Йонсана и Чхонана."}}$nsd$::jsonb || localized_content
 where region_id = 'a2000000-0000-4000-8000-000000000001' and localized_content->'ko'->>'name' = $nsd$홍성역$nsd$;
